import {b,a,f,s,c} from '../authoring.js';

// Worked examples, not captured server output. Identifiers and page sizes are illustrative.
const who=(key,name,lines=[])=>a(key,'client',name,({'Читатель':'Reader','Приложение':'Application'}[name]||name),lines);
const box=(key,ru,en,lines=[])=>a(key,'status',ru,en,lines);
const tab=(key,ru,en,columns,rows)=>a(key,'table',ru,en,[],{columns,rows});
const pg=(key,rows)=>a(key,'page','Страница таблицы','Heap page',[],{columns:['slot','version','state'],rows});
const seq=(key,ru,en,items)=>a(key,'timeline',ru,en,[],{items});
const tree=(key,ru,en,nodes,edges)=>a(key,'tree',ru,en,[],{nodes:nodes.map(([id,label])=>({id,label})),edges});
const plan=(nodes,edges)=>a('plan','plan','План','Plan',[],{nodes:nodes.map(([id,label])=>({id,label})),edges});
const bucket=(items)=>a('hash','buckets','Хеш-таблица','Hash table',[],{items});
const snapshot=()=>box('snapshot','Старый снимок','Old snapshot',['account A: 10','needs version v1']);
const joinL=()=>tab('left','Левая таблица','Left table',['rid','k'],[['L1','1'],['L2','1'],['L3','2']]);
const joinR=()=>tab('right','Правая таблица','Right table',['rid','k'],[['R1','1'],['R2','1'],['R3','3']]);
const pairs=(rows)=>tab('result','Пары результата','Result pairs',['left.rid','right.rid'],rows);
const matched=[['L1','R1'],['L1','R2'],['L2','R1'],['L2','R2']];
const joinSetup="CREATE TEMP TABLE join_l (rid text, k integer);\nINSERT INTO join_l VALUES ('L1',1),('L2',1),('L3',2);\nCREATE TEMP TABLE join_r (rid text, k integer);\nINSERT INTO join_r VALUES ('R1',1),('R2',1),('R3',3);";

export const chapters=[
  c({number:25,id:'table-locks',group:3,title:['Кто мешает изменить таблицу','Who blocks a table change'],question:['Чтение не запирает строки. Почему ALTER TABLE ждёт?','Reads do not lock rows. Why does ALTER TABLE wait?'],next:['Несколько транзакций могут вместе защищать одну строку. Как это записать?','Several transactions can protect one row together. How is that recorded?'],docs:['explicit-locking.html','view-pg-locks.html'],book:[255,267],steps:[
    s('A читает заказы и оставляет транзакцию открытой.','A reads orders and leaves its transaction open.',[who('A','A',['transaction open'])],[], 'BEGIN;\nSELECT * FROM orders;', 'SELECT берёт ACCESS SHARE на таблицу; обычное чтение не требует блокировки каждой строки.','SELECT takes ACCESS SHARE on the table; ordinary reads do not need a lock on every row.'),
    s('B тоже читает orders: две блокировки ACCESS SHARE совместимы.','B also reads orders: two ACCESS SHARE locks are compatible.',[who('A','A',['ACCESS SHARE']),box('orders','Таблица orders','Table orders',['ACCESS SHARE: A, B']),who('B','B',['ACCESS SHARE'])],[f('B','orders','SELECT')], 'SELECT * FROM orders;', 'Совместимость определяется режимами блокировки одного объекта, а не правилом «одна таблица — один владелец».','Compatibility depends on lock modes on the same object, rather than one owner per table.'),
    s('C хочет добавить столбец. Его ACCESS EXCLUSIVE ждёт завершения чтения.','C wants to add a column. Its ACCESS EXCLUSIVE waits for the readers.',[who('A','A',['ACCESS SHARE']),box('orders','Таблица orders','Table orders',['granted: A','C: waiting']),who('C','C',['ACCESS EXCLUSIVE'])],[f('C','orders','ALTER TABLE','wait')], 'ALTER TABLE orders ADD COLUMN fulfilment_note text;', 'Предположим, B уже завершил запрос. Блокировку A сохраняет открытая транзакция; этот ALTER TABLE требует несовместимый режим.','Assume B has finished. A retains its lock in an open transaction; this ALTER TABLE needs an incompatible mode.'),
    s('A завершает транзакцию. Теперь C может изменить определение таблицы.','A ends its transaction. C can now change the table definition.',[who('A','A',['COMMIT']),box('orders','Таблица orders','Table orders',['ACCESS EXCLUSIVE: C','fulfilment_note: text']),who('C','C',['ALTER complete'])],[f('A','orders','release','internal'),f('orders','C','ALTER TABLE','reply')], 'COMMIT;', 'Обычные табличные блокировки освобождаются при завершении транзакции. Блокировки после savepoint могут освобождаться при откате к нему.','Ordinary table locks last until transaction end. Locks acquired after a savepoint can be released by rolling back to it.'),
    s('ROW EXCLUSIVE — тоже блокировка таблицы. Её название не означает одну строку.','ROW EXCLUSIVE is also a table lock. Its name does not mean a single row.',[tab('modes','Разные уровни','Different levels',['operation','table mode','row lock'],[['SELECT','ACCESS SHARE','none'],['UPDATE','ROW EXCLUSIVE','target row'],['ALTER','ACCESS EXCLUSIVE','not a row lock']])],[], '', 'У UPDATE есть и табличная блокировка, и отдельная защита изменяемых строк. Один режим не заменяет другой.','UPDATE has a table lock plus separate protection of changed rows. These are different lock levels.'),
  ]}),
  c({number:26,id:'multixact',group:3,title:['Одна строка, несколько владельцев','One row, several lockers'],question:['Как одна строка помнит нескольких совместимых владельцев?','How does one row remember several compatible lockers?'],next:['А если каждый ждёт строку, занятую другим?','What if each transaction waits for a row held by the other?'],docs:['explicit-locking.html','routine-vacuuming.html','storage-page-layout.html'],book:[268,292],steps:[
    s('A защищает ключ заказа от удаления, но не меняет его данные.','A protects an order key from deletion without changing its data.',[who('A','A',['FOR KEY SHARE'])],[], 'BEGIN;\nSELECT * FROM orders WHERE id = 1 FOR KEY SHARE;', 'KEY SHARE совместим с другим KEY SHARE и с обновлением, не меняющим ключ. Он конфликтует с удалением или FOR UPDATE.','KEY SHARE allows other KEY SHARE locks and non-key updates. It conflicts with deletion or FOR UPDATE.'),
    s('B тоже берёт KEY SHARE. Обоим разрешено держать эту строку.','B also takes KEY SHARE. Both may hold this row.',[who('A','A',['KEY SHARE']),pg('row',[['1','order 1','locked']]),who('B','B',['KEY SHARE'])],[f('B','row','KEY SHARE')], 'BEGIN;\nSELECT * FROM orders WHERE id = 1 FOR KEY SHARE;', 'Совместимые блокировки строки могут принадлежать нескольким транзакциям одновременно.','Several transactions can hold compatible locks on a row at the same time.'),
    s('В xmax теперь указан MultiXact: его участники хранятся отдельно.','xmax now identifies a MultiXact; its members are stored separately.',[pg('row',[['1','xmax = MX7','lock-only']]),tab('members','Участники MX7','MX7 members',['transaction','mode'],[['A','KEY SHARE'],['B','KEY SHARE']])],[f('row','members','MX7','internal')], '', 'MX7 — условное обозначение. Флаги заголовка показывают, что xmax содержит MultiXact, а не обычный номер удалившей транзакции.','MX7 is an illustrative label. Tuple-header flags distinguish a MultiXact in xmax from an ordinary deleting transaction ID.'),
    s('C пытается удалить строку и ждёт, пока уйдут оба несовместимых владельца.','C tries to delete the row and waits for both conflicting lockers to leave.',[tab('members','Участники MX7','MX7 members',['transaction','state'],[['A','active'],['B','active']]),pg('row',[['1','order 1','protected']]),who('C','C',['DELETE waits'])],[f('C','row','DELETE','wait')], 'DELETE FROM orders WHERE id = 1;', 'Завершение одного владельца недостаточно, пока остаётся другой конфликтующий участник. MultiXact не означает несколько одновременных обновлений строки.','One locker finishing is insufficient while another conflicting member remains. A MultiXact does not mean several simultaneous row updates.'),
    s('A и B завершились. C продолжает удаление, а старые MultiXact требуют обслуживания.','A and B finish. C can delete; old MultiXacts still need maintenance.',[tab('members','Участники MX7','MX7 members',['transaction','state'],[['A','committed'],['B','committed']]),pg('row',[['1','order 1','deleted by C']]),who('C','C',['DELETE 1'])],[f('row','C','DELETE 1','reply')], '', 'VACUUM удаляет ненужные старые ссылки MultiXact и продвигает relminmxid. Этот счётчик имеет собственную защиту от переполнения.','VACUUM replaces obsolete MultiXact references and advances relminmxid. This counter has its own wraparound protection.'),
  ]}),
  c({number:27,id:'deadlock',group:3,title:['Ожидание замкнулось в круг','Waiting forms a cycle'],question:['Почему два корректных UPDATE могут остановить друг друга?','Why can two valid UPDATEs stop each other?'],next:['Всегда ли приложению нужно ждать блокировку?','Must the application always wait for a lock?'],docs:['explicit-locking.html','errcodes-appendix.html'],book:[286,292],steps:[
    s('A меняет счёт 1. B уже меняет счёт 2. Каждый удерживает свою строку.','A changes account 1. B already changes account 2. Each holds a different row.',[who('A','A',['holds account 1']),tab('accounts','Счета','Accounts',['id','owner'],[['1','A'],['2','B']]),who('B','B',['holds account 2'])],[], "CREATE TABLE deadlock_accounts (id integer PRIMARY KEY, balance integer NOT NULL);\nINSERT INTO deadlock_accounts VALUES (1,100),(2,100);\n-- Session A\nBEGIN;\nUPDATE deadlock_accounts SET balance = balance - 10 WHERE id = 1;\n-- Session B\nBEGIN;\nUPDATE deadlock_accounts SET balance = balance - 10 WHERE id = 2;", 'Пока каждый меняет свою строку, конфликта нет. Оба намерены продолжить ту же транзакцию.','There is no conflict while each changes its own row. Both intend to continue the same transaction.'),
    s('A просит счёт 2 и ждёт B. Удерживаемый A счёт 1 остаётся занят.','A requests account 2 and waits for B. A still holds account 1.',[who('A','A',['waits for B']),tab('accounts','Счета','Accounts',['id','owner'],[['1','A'],['2','B']]),who('B','B',['holds account 2'])],[f('A','B','needs account 2','wait')], '-- Session A\nUPDATE deadlock_accounts SET balance = balance + 10 WHERE id = 2;', 'Ожидание второй блокировки само по себе не освобождает уже полученную первую.','Waiting for the second lock does not release the first lock already held.'),
    s('B теперь просит счёт 1. A ждёт B, а B ждёт A: продолжить не может никто.','B now requests account 1. A waits for B and B waits for A; neither can continue.',[who('A','A',['holds 1; needs 2']),who('B','B',['holds 2; needs 1'])],[f('A','B','2','wait'),f('B','A','1','wait')], '-- Session B\nUPDATE deadlock_accounts SET balance = balance + 10 WHERE id = 1;', 'Deadlock — цикл зависимостей ожидания. Просто долгая очередь без цикла ещё не является взаимоблокировкой.','A deadlock is a cycle in wait dependencies. A long queue without a cycle is not yet a deadlock.'),
    s('Сервер прерывает одну транзакцию. В нашем примере это B; A освобождается.','The server aborts one transaction. In this example it is B, letting A proceed.',[who('A','A',['can continue']),who('B','B',['40P01: deadlock']),tab('accounts','Счета','Accounts',['id','state'],[['1','held by A'],['2','released by B']])],[f('B','accounts','release','internal')], '-- Session B: after the deadlock error\nROLLBACK;', 'Выбор жертвы не гарантирован. Приложение должно повторять целую прерванную транзакцию, а не только последний UPDATE.','Victim selection is not guaranteed. The application should retry the entire aborted transaction, not just its last UPDATE.'),
    s('Оба приложения берут счета в порядке 1, затем 2. Теперь есть очередь, но нет круга.','Both applications acquire accounts in order 1, then 2. There is a queue, but no cycle.',[seq('order','Единый порядок','One lock order',['A: 1 -> 2 -> COMMIT','B: wait 1 -> 1 -> 2'])],[], 'BEGIN;\nSELECT id FROM deadlock_accounts WHERE id IN (1,2) ORDER BY id FOR UPDATE;\nCOMMIT;', 'Одинаковый порядок блокировок предотвращает этот цикл. Более сложная транзакция всё равно должна обрабатывать deadlock и повтор.','A consistent lock order prevents this cycle. More complex transactions still need deadlock handling and retries.'),
  ]}),
  c({number:28,id:'lock-options',group:3,title:['Подождать, отказаться или пропустить','Wait, fail or skip'],question:['Занятая задача должна останавливать всех работников?','Should one locked job stop every worker?'],next:['Почему короткое ожидание бывает даже без конфликта строк?','Why can a short wait occur without conflicting row locks?'],docs:['sql-select.html','runtime-config-client.html','explicit-locking.html'],book:[268,304],steps:[
    s('Работник A обрабатывает задачу 1 и пока держит её строку.','Worker A is processing job 1 and still holds its row.',[who('A','A',['job 1 locked']),tab('jobs','Очередь задач','Job queue',['id','status'],[['1','ready'],['2','ready'],['3','ready']])],[f('A','jobs','FOR UPDATE')], "CREATE TABLE jobs (id integer PRIMARY KEY, status text);\nINSERT INTO jobs VALUES (1,'ready'),(2,'ready'),(3,'ready');\nBEGIN;\nSELECT id FROM jobs WHERE status = \'ready\' ORDER BY id LIMIT 1 FOR UPDATE;", 'Строка остаётся со status=ready до изменения, но её несовместимая блокировка уже принадлежит A.','The row remains ready until changed, but A already holds its conflicting row lock.'),
    s('Обычный FOR UPDATE у B ждёт задачу 1, хотя рядом есть свободная задача 2.','Ordinary FOR UPDATE makes B wait for job 1 despite job 2 being available.',[who('A','A',['job 1 locked']),tab('jobs','Очередь задач','Job queue',['id','row lock'],[['1','A'],['2','free'],['3','free']]),who('B','B',['waiting'])],[f('B','jobs','FOR UPDATE','wait')], 'SELECT id FROM jobs WHERE status = \'ready\' ORDER BY id LIMIT 1 FOR UPDATE;', 'ORDER BY и LIMIT выбирают кандидата; несовместимая блокировка заставляет обычный запрос ждать.','ORDER BY and LIMIT select a candidate; a conflicting row lock makes the ordinary request wait.'),
    s('NOWAIT возвращает ошибку сразу: B может выбрать другое действие.','NOWAIT returns an error immediately, letting B choose another action.',[tab('jobs','Очередь задач','Job queue',['id','row lock'],[['1','A'],['2','free']]),who('B','B',['55P03'])],[f('B','jobs','NOWAIT'),f('jobs','B','55P03','reply')], 'SELECT id FROM jobs WHERE status = \'ready\' ORDER BY id LIMIT 1 FOR UPDATE NOWAIT;', 'Это альтернативная попытка B. В явной транзакции ошибка требует ROLLBACK либо отката к savepoint перед продолжением.','This is an alternative B attempt. Inside an explicit transaction the error requires ROLLBACK or rollback to a savepoint before continuing.'),
    s('SKIP LOCKED пропускает строку 1. B получает задачу 2 и блокирует её.','SKIP LOCKED skips row 1. B obtains job 2 and locks it.',[who('A','A',['job 1']),tab('jobs','Очередь задач','Job queue',['id','row lock'],[['1','A'],['2','B'],['3','free']]),who('B','B',['job 2'])],[f('B','jobs','SKIP LOCKED'),f('jobs','B','2','reply')], 'BEGIN;\nSELECT id FROM jobs WHERE status = \'ready\' ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED;', 'Пропуск полезен для очереди работников, но даёт неполный, несогласованный обзор набора. Табличные блокировки всё ещё могут заставить ждать.','Skipping suits a worker queue but gives an incomplete, inconsistent view of the set. Required table locks can still cause waits.'),
    s('B меняет статус задачи и завершает транзакцию. Один SELECT ещё не обработал её.','B updates the job status and commits. Selecting a job alone did not process it.',[tab('jobs','Очередь задач','Job queue',['id','status'],[['1','ready'],['2','running'],['3','ready']]),who('B','B',['COMMIT'])],[f('B','jobs','UPDATE')], 'UPDATE jobs SET status = \'running\' WHERE id = 2;\nCOMMIT;', 'Резервирование и обработка — разные действия. После падения работника приложению нужен собственный протокол возврата зависшей задачи.','Claiming and processing are different actions. The application needs its own recovery protocol for a worker that crashes.'),
    s('lock_timeout ограничивает ожидание блокировки; это не общий таймер всего запроса.','lock_timeout bounds a lock wait; it is not a timer for the whole query.',[seq('wait','Граница ожидания','Waiting boundary',['request lock','wait up to 500 ms','error or granted'])],[], "BEGIN;\nSET LOCAL lock_timeout = '500ms';\nSELECT * FROM jobs WHERE id = 1 FOR UPDATE;\nROLLBACK;", 'Значение учебное. Лимит применяется отдельно к попыткам получения блокировки; statement_timeout ограничивает выполнение оператора в целом.','The value is illustrative. The limit applies to individual lock-acquisition attempts; statement_timeout limits the overall statement.'),
  ]}),
  c({number:29,id:'internal-locks',group:3,title:['Защита общих структур в памяти','Protecting shared memory'],question:['Клиенты не спорят за строку. Что ещё может заставить процесс ждать?','Clients do not conflict on a row. What else can make a process wait?'],next:['Кто решает, что старую версию уже безопасно удалить?','Who decides when an old version is safe to remove?'],docs:['monitoring-stats.html','explicit-locking.html','view-pg-locks.html'],book:[305,316],steps:[
    s('A и B читают одну страницу через общий буферный кеш.','A and B read the same page through the shared buffer cache.',[who('A','A'),a('buffer','page','Общий буфер','Shared buffer',['page 7']),who('B','B')],[f('A','buffer','read'),f('B','buffer','read')], '', 'Защищать нужно не только бизнес-строки, но и сами общие структуры: отображение страниц, заголовки буферов и их содержимое.','Shared structures also need protection: page mappings, buffer headers and buffer contents, not only business rows.'),
    s('LWLock ненадолго защищает общую структуру, пока процесс меняет её.','An LWLock briefly protects a shared structure while a process changes it.',[who('A','A',['short critical section']),box('guard','Лёгкая блокировка','Lightweight lock',['shared memory']),who('B','B',['may wait'])],[f('A','guard','LWLock','internal'),f('B','guard','wait','wait')], '', 'LWLock — внутренний механизм синхронизации. Его не берут SQL-командой LOCK TABLE и не держат до COMMIT по общему правилу.','An LWLock is internal synchronization. It is not acquired with LOCK TABLE and does not generally last until COMMIT.'),
    s('Pin не даёт вытеснить используемый буфер. Это не монопольное владение его данными.','A pin keeps an in-use buffer from eviction. It is not exclusive ownership of its data.',[who('A','A',['pin count +1']),a('buffer','page','Общий буфер','Shared buffer',['page 7','pinned']),box('replace','Вытеснение','Eviction',['choose another buffer'])],[f('A','buffer','pin','internal')], '', 'Несколько процессов могут закрепить один буфер. Блокировка содержимого и pin решают разные задачи; pin сам по себе не запрещает чтение другими.','Several processes may pin the same buffer. Content locking and pinning solve different problems; a pin alone does not prevent other readers.'),
    s('Событие ожидания отличает Lock, LWLock и BufferPin. Причину нужно искать на своём уровне.','Wait events distinguish Lock, LWLock and BufferPin. Diagnose the appropriate level.',[tab('waits','Наблюдение','Observation',['wait_event_type','protects'],[['Lock','SQL objects'],['LWLock','shared structure'],['BufferPin','buffer lifetime']])],[], 'SELECT pid, wait_event_type, wait_event FROM pg_stat_activity WHERE wait_event IS NOT NULL;', 'pg_locks показывает тяжёлые блокировки, но не является полным списком всех внутренних ожиданий. Названия здесь — категории, не снимок сервера.','pg_locks exposes heavyweight locks, not a complete list of internal waits. These labels are categories, not a captured server snapshot.'),
  ]}),
  c({number:30,id:'cleanup-horizon',group:3,title:['Кто ещё видит старую версию','Who still sees the old version'],question:['UPDATE завершён. Почему старая версия всё ещё нужна?','UPDATE has committed. Why is its old version still needed?'],next:['Как уменьшить цену обновлений, не отменяя версии?','How can updates become cheaper without abandoning versions?'],docs:['mvcc-intro.html','transaction-iso.html','routine-vacuuming.html'],book:[97,110],steps:[
    s('A начинает REPEATABLE READ и видит баланс счёта A, равный 10.','A starts REPEATABLE READ and sees account A with a balance of 10.',[who('A','A',['REPEATABLE READ'])],[], 'UPDATE accounts SET balance = 10 WHERE id = \'A\';\nBEGIN ISOLATION LEVEL REPEATABLE READ;\nSELECT balance FROM accounts WHERE id = \'A\';', 'Это новый пример, начинающийся с баланса 10. Снимок устанавливается первым запросом к данным, а не самим BEGIN. В этом примере он должен оставаться неизменным.','This new example starts with balance 10. The data snapshot is established by the first data query, not BEGIN itself. It must remain stable in this example.'),
    s('B меняет баланс на 20 и фиксирует его. На странице остаются v1 и v2.','B changes the balance to 20 and commits. Both v1 and v2 remain on the page.',[snapshot(),pg('heap',[['1','v1: 10','old'],['2','v2: 20','committed']]),who('B','B',['COMMIT'])],[f('B','heap','UPDATE')], '-- Session B\nUPDATE accounts SET balance = 20 WHERE id = \'A\';', 'B использует отдельную autocommit-сессию. Для новых снимков актуальна v2, но это ещё не делает v1 ненужной всем.','B uses a separate autocommit session. New snapshots see v2, but that does not make v1 obsolete for everyone.'),
    s('Повторное чтение A возвращает 10. Удаление v1 нарушило бы обещание снимка.','A reads again and gets 10. Removing v1 would break its snapshot guarantee.',[snapshot(),pg('heap',[['1','v1: 10','visible to A'],['2','v2: 20','newer than A']])],[f('snapshot','heap','SELECT'),f('heap','snapshot','10','reply')], '-- Session A\nSELECT balance FROM accounts WHERE id = \'A\';', 'Горизонт очистки учитывает потенциальных читателей старых версий; факт COMMIT у B — только часть проверки.','The cleanup horizon accounts for potential readers of old versions; B committing is only part of the check.'),
    s('VACUUM приходит раньше завершения A и оставляет нужную ему v1 на месте.','VACUUM arrives before A finishes and leaves the v1 that A still needs.',[snapshot(),pg('heap',[['1','v1: 10','retain'],['2','v2: 20','retain']]),box('vac','VACUUM','VACUUM',['cannot reclaim v1'])],[f('vac','heap','check horizon','internal')], '-- Separate maintenance session\nVACUUM accounts;', 'Долгие снимки, подготовленные транзакции и некоторые replication slots могут удерживать очистку. Просто чаще запускать VACUUM недостаточно.','Long-lived snapshots, prepared transactions and some replication slots can retain cleanup horizons. Running VACUUM more often is insufficient.'),
    s('A завершает транзакцию. Когда других удерживающих причин нет, v1 можно освободить.','A finishes. If no other retention remains, v1 can be reclaimed.',[who('A','A',['COMMIT']),pg('heap',[['1','v1: 10','reclaimable'],['2','v2: 20','current']]),box('vac','Очистка','Cleanup',['horizon advanced'])],[f('A','vac','release snapshot','internal')], '-- Session A\nCOMMIT;', 'Завершение A разрешает будущую очистку, а не выполняет её мгновенно. Показанный горизонт логический, не числовой вывод PostgreSQL.','A finishing permits later cleanup rather than performing it instantly. This is a logical horizon, not numeric PostgreSQL output.'),
  ]}),
  c({number:31,id:'hot',group:4,title:['Обновление без новых записей индекса','Updating without new index entries'],question:['Нужно ли каждому новому варианту строки заново попадать во все индексы?','Must every row version add entries to every index?'],next:['Где найти свободное место и как узнать видимость страницы?','Where can free space be found, and how is page visibility known?'],docs:['storage-hot.html','storage-page-layout.html'],book:[111,124],steps:[
    s('Индекс по id ведёт к Alice на странице 7. Меняем только её имя.','An index on id points to Alice on page 7. We change only her name.',[tree('idx','Индекс id','Index on id',[['root','id = 1'],['leaf','TID (7,1)']],[['root','leaf']]),pg('heap',[['1','Alice','current'],['2','free','space']])],[f('idx','heap','(7,1)','internal')], "CREATE TEMP TABLE hot_demo (id integer PRIMARY KEY, name text) WITH (fillfactor = 70);\nINSERT INTO hot_demo VALUES (1,'Alice');", 'Предположим, name не используется ни одним обычным индексом, выражением или предикатом индекса, а на этой странице хватает места.','Assume name is absent from ordinary index keys, expressions and predicates, and the same page has enough space.'),
    s('Новая версия Alicia помещается рядом. Старая версия связывается с ней.','The new Alicia version fits alongside. The old version links to it.',[tree('idx','Индекс id','Index on id',[['root','id = 1'],['leaf','TID (7,1)']],[['root','leaf']]),pg('heap',[['1','Alice -> (7,2)','old'],['2','Alicia','current']])],[f('idx','heap','same TID','internal')], "UPDATE hot_demo SET name = 'Alicia' WHERE id = 1;", 'HOT позволяет оставить прежнюю запись обычного индекса. Связь версий остаётся внутри одной heap-страницы.','HOT keeps the existing ordinary index entry. Its version chain stays within one heap page.'),
    s('Чтение идёт по прежнему TID, затем выбирает видимую версию цепочки.','A read follows the original TID, then chooses the visible version in its chain.',[who('reader','Читатель',['snapshot']),tree('idx','Индекс id','Index on id',[['root','id = 1'],['leaf','TID (7,1)']],[['root','leaf']]),pg('heap',[['1','Alice -> (7,2)','old'],['2','Alicia','visible now']])],[f('reader','idx','id = 1'),f('idx','heap','follow chain','internal'),f('heap','reader','Alicia','reply')], 'SELECT name FROM hot_demo WHERE id = 1;', 'Для подходящего старого снимка ответ мог бы остаться Alice. HOT оптимизирует размещение, но не меняет правила видимости.','A suitable old snapshot could still return Alice. HOT optimizes storage without changing visibility rules.'),
    s('Когда Alice никому не нужна, pruning оставляет перенаправление к живой версии.','When nobody needs Alice, pruning leaves a redirect to the live version.',[tree('idx','Индекс id','Index on id',[['root','id = 1'],['leaf','TID (7,1)']],[['root','leaf']]),pg('heap',[['1','redirect -> 2','line pointer'],['2','Alicia','current']])],[f('idx','heap','redirect','internal')], '', 'Очищать часть HOT-цепочки можно при обычной работе со страницей. Перенаправление сохраняет путь от существующей записи индекса.','Parts of a HOT chain can be pruned during ordinary page access. A redirect preserves the path from the existing index entry.'),
    s('Изменили индексируемый id или не хватило места? Это обновление уже не HOT.','Changed an indexed id or ran out of page space? This update is no longer HOT.',[tab('rules','Условия HOT','HOT conditions',['case','ordinary index'],[['same page; key unchanged','reuse entry'],['indexed value changed','new entries'],['new page required','new entries']])],[], '', 'Исключение: суммирующие индексы, в ядре BRIN, не запрещают HOT сами по себе и могут обновлять свои сводки. fillfactor может оставить место на странице.','Summarizing indexes, BRIN in core, do not by themselves prevent HOT and may still update summaries. A lower fillfactor can reserve page space.'),
  ]}),
  c({number:32,id:'maps',group:4,title:['Две карты рядом с таблицей','Two maps beside a table'],question:['Нужно ли просматривать все страницы ради свободного места или видимости?','Must every page be inspected for free space or visibility?'],next:['Кто убирает ненужные версии и обновляет эти сведения?','Who removes obsolete versions and updates these facts?'],docs:['storage-fsm.html','storage-vm.html','indexes-index-only-scans.html'],book:[125,137],steps:[
    s('Новой строке нужно место. У страниц 0, 1 и 2 его разное количество.','A new row needs space. Pages 0, 1 and 2 have different amounts available.',[tab('heap','Страницы heap','Heap pages',['page','free bytes'],[['0','80'],['1','1200'],['2','200']])],[], '', 'Числа учебные и не являются точным содержимым FSM. Проверять все страницы перед каждой вставкой было бы дорого.','The numbers are illustrative, not exact FSM contents. Checking every page before each insert would be expensive.'),
    s('Free Space Map подсказывает страницу 1. Перед вставкой место проверяют на самой странице.','The Free Space Map suggests page 1. Its space is checked again before insertion.',[box('insert','Новая строка','New row',['needs 600 bytes']),tree('fsm','Карта свободного места','Free Space Map',[['root','max free'],['p0','p0: small'],['p1','p1: enough'],['p2','p2: small']],[['root','p0'],['root','p1'],['root','p2']]),pg('page1',[['1','new row','600 bytes']])],[f('insert','fsm','find space','internal'),f('fsm','page1','page 1','internal')], '', 'FSM хранит округлённые сведения, которые могут устаревать. Подсказка не резервирует страницу и не заменяет окончательную проверку.','FSM holds rounded information that can become stale. A hint neither reserves a page nor replaces the final check.'),
    s('Visibility Map отвечает на другой вопрос: все ли строки страницы видимы всем?','The Visibility Map asks a different question: are all page rows visible to everyone?', [tab('vm','Карта видимости','Visibility Map',['page','all-visible','all-frozen'],[['0','1','0'],['1','0','0'],['2','1','1']])],[], '', 'У каждой heap-страницы два бита. Установленный бит — достоверное обещание; ноль означает отсутствие обещания, а не обязательно невидимую строку.','Each heap page has two bits. A set bit is a reliable promise; zero means no promise, not necessarily an invisible row.'),
    s('Index-only scan на странице 0 проверяет all-visible и может не читать heap.','An index-only scan for page 0 checks all-visible and may avoid reading the heap.',[tree('idx','Покрывающий индекс','Covering index',[['i','id, name; TID (0,1)']],[]),tab('vm','Карта видимости','Visibility Map',['page','all-visible'],[['0','1']]),who('reader','Читатель',['Alicia'])],[f('idx','vm','visibility?','internal'),f('idx','reader','Alicia','reply')], "CREATE INDEX hot_demo_cover ON hot_demo (id) INCLUDE (name);\nVACUUM hot_demo;\nSELECT name FROM hot_demo WHERE id = 1;", 'Здесь все нужные значения доступны из подходящего индекса. При нулевом бите пришлось бы проверить видимость версии в heap.','All required values are available from a suitable index here. A zero bit would require checking tuple visibility in the heap.'),
    s('Изменение страницы сбрасывает обещание VM. VACUUM сможет установить его заново после проверки.','Changing a page clears its VM promise. VACUUM can set it again after checking.',[pg('page0',[['1','Alicia -> Alice','updated']]),tab('vm','Карта видимости','Visibility Map',['page','all-visible','all-frozen'],[['0','0','0']]),box('vac','VACUUM','VACUUM',['check before setting'])],[f('page0','vm','clear bits','internal')], "UPDATE hot_demo SET name = 'Alice' WHERE id = 1;", 'FSM описывает место, VM — доказанную видимость и заморозку. Это служебные карты страниц, а не дополнительные пользовательские индексы.','FSM describes space; VM records proven visibility and freezing. They are page-maintenance maps, not extra user indexes.'),
  ]}),
  c({number:33,id:'vacuum',group:4,title:['Освободить место безопасно','Reclaim space safely'],question:['Снимок отпущен. Как убрать версии, не оставив индекс указывать в пустоту?','The snapshot is gone. How are versions removed without dangling index references?'],next:['Кто запускает эту работу без ручного расписания?','Who starts this work without a manual schedule?'],docs:['sql-vacuum.html','progress-reporting.html','routine-vacuuming.html'],book:[125,137],steps:[
    s('Версия Bob уже не нужна ни одному снимку, но её место и запись индекса пока заняты.','No snapshot needs Bob anymore, but its space and index entry remain.',[pg('heap',[['1','Alice','live'],['2','Bob','dead']]),tab('idx','Записи индекса','Index entries',['key','TID'],[['1','(7,1)'],['2','(7,2)']])],[], "CREATE TEMP TABLE vacuum_demo (id integer PRIMARY KEY, name text);\nINSERT INTO vacuum_demo VALUES (1,'Alice'),(2,'Bob');\nDELETE FROM vacuum_demo WHERE id = 2;", 'Рассматриваем обычный не-HOT случай с индексом и разрешённой очисткой индексов. Удалённая строка не означает мгновенно свободный слот.','This is a non-HOT example with an index and index cleanup enabled. A deleted row does not imply an immediately reusable slot.'),
    s('VACUUM сканирует heap, проверяет горизонт и собирает адреса мёртвых версий.','VACUUM scans the heap, checks the horizon and collects dead-version addresses.',[pg('heap',[['1','Alice','live'],['2','Bob','dead item']]),a('dead','queue','Адреса для очистки','Dead item addresses',[],{items:['(7,2)']}),box('vac','Сканирование heap','Scanning heap')],[f('vac','heap','scan','internal'),f('heap','dead','(7,2)','internal')], 'VACUUM vacuum_demo;', 'При сканировании возможны pruning, уплотнение страницы и freezing. Освобождение индексируемого item identifier требует ещё убрать ссылки индекса.','The scan may prune, defragment and freeze. Reusing an indexed item identifier also requires removing index references.'),
    s('Сначала удаляются записи индекса, ведущие к собранным мёртвым адресам.','Index entries pointing to the collected dead addresses are removed first.',[a('dead','queue','Адреса для очистки','Dead item addresses',[],{items:['(7,2)']}),tab('idx','Записи индекса','Index entries',['key','TID'],[['1','(7,1)']]),pg('heap',[['1','Alice','live'],['2','dead item','not reused yet']])],[f('dead','idx','vacuum indexes','internal')], '', 'Пока ссылка индекса существует, адрес нельзя отдать совершенно другой строке. Здесь показан полный цикл, а не все возможные оптимизации VACUUM.','While an index reference exists, its address cannot be handed to an unrelated row. This shows a full cleanup cycle, not every VACUUM optimization.'),
    s('Затем VACUUM возвращается в heap и освобождает эти слоты для повторного использования.','VACUUM then revisits the heap and frees those slots for reuse.',[tab('idx','Записи индекса','Index entries',['key','TID'],[['1','(7,1)']]),pg('heap',[['1','Alice','live'],['2','free','reusable']]),box('vac','Очистка heap','Vacuuming heap')],[f('vac','heap','reclaim items','internal')], '', 'Если буфер адресов заполнился, циклы «сканирование → индексы → heap» могут повторяться. Таблица без индексов допускает более прямую очистку.','If dead-address memory fills, scan/index/heap cycles may repeat. A table without indexes permits more direct cleanup.'),
    s('Карты и счётчики обновляются. Пустой хвост файла иногда можно обрезать.','Maps and counters are updated. An empty file tail can sometimes be truncated.',[pg('heap',[['1','Alice','live'],['2','free','reusable']]),tab('maps','Служебные сведения','Maintenance data',['map','meaning'],[['FSM','reusable space'],['VM','proven visibility']]),seq('phases','Окончание цикла','Finishing the cycle',['index cleanup','optional tail truncation','final cleanup'])],[f('heap','maps','record state','internal')], '', 'Обрезка хвоста требует подходящей блокировки. Обычный VACUUM в основном делает место доступным внутри файла, а не уменьшает его размер.','Tail truncation requires a suitable lock. Ordinary VACUUM mainly makes space reusable inside the file, rather than shrinking it.'),
    s('Новая строка использует свободное место. Для статистики распределения данных отдельно нужен ANALYZE.','A new row reuses the space. Data-distribution statistics separately require ANALYZE.',[pg('heap',[['1','Alice','live'],['2','Carol','new live row']]),box('analyze','Статистика столбцов','Column statistics',['ANALYZE'])],[f('analyze','heap','sample','internal')], "INSERT INTO vacuum_demo VALUES (3,'Carol');\nVACUUM (ANALYZE) vacuum_demo;", 'VACUUM обновляет служебные оценки таблицы; ANALYZE собирает распределения значений для планировщика. Один можно явно сочетать с другим.','VACUUM updates table maintenance estimates; ANALYZE gathers value distributions for the planner. They can be explicitly combined.'),
  ]}),
  c({number:34,id:'autovacuum',group:4,title:['Уборка приходит сама','Cleanup starts automatically'],question:['Таблицы меняются постоянно. Кто замечает, что пора убирать?','Tables change continuously. Who notices when cleanup is due?'],next:['Зачем обслуживать даже таблицу почти без изменений?','Why maintain even a table that hardly changes?'],docs:['routine-vacuuming.html','runtime-config-vacuum.html','monitoring-stats.html'],book:[138,169],steps:[
    s('В orders накапливаются старые версии. Ручной VACUUM ещё никто не запускал.','Old versions accumulate in orders. Nobody has run manual VACUUM yet.',[tab('orders','Таблица orders','Table orders',['estimate','value'],[['live rows','1000'],['obsolete rows','240']])],[], '', 'Счётчики статистики являются оценками и обновляются не мгновенно. Здесь числа выбраны для прозрачного расчёта порога.','Statistics counters are estimates and are not updated instantly. These numbers make the threshold calculation transparent.'),
    s('Для выбранных настроек порог равен 50 + 0,2 × 1000 = 250. Пока 240 меньше порога.','With our settings the threshold is 50 + 0.2 × 1000 = 250. So far 240 is below it.',[tab('orders','Таблица orders','Table orders',['estimate','value'],[['live rows','1000'],['obsolete rows','240']]),box('threshold','Учебные настройки','Example settings',['base = 50','scale = 0.2','threshold = 250'])],[], '', 'Используем явные учебные значения и максимум выше 250. Формула для UPDATE/DELETE учитывает также верхний предел autovacuum_vacuum_max_threshold.','We choose explicit values and a maximum above 250. The UPDATE/DELETE formula also applies autovacuum_vacuum_max_threshold.'),
    s('Число старых версий выросло до 260. Таблица стала кандидатом на autovacuum.','The obsolete count reaches 260. The table becomes an autovacuum candidate.',[tab('orders','Таблица orders','Table orders',['obsolete','threshold'],[['260','250']]),box('launcher','Launcher','Launcher',['schedule database work']),box('worker','Worker','Worker',['orders eligible'])],[f('launcher','worker','start worker','internal')], '', 'Превышение порога не обещает немедленного запуска: нужны свободный worker, проверка базы и получение блокировки.','Crossing a threshold does not promise immediate execution: a worker, database check and suitable lock are still needed.'),
    s('Worker выполняет обычный VACUUM. Параллельные чтения и записи могут продолжаться.','The worker performs ordinary VACUUM. Concurrent reads and writes may continue.',[box('worker','Worker','Worker',['VACUUM orders']),tab('orders','Таблица orders','Table orders',['state','meaning'],[['dead space','reusable'],['old snapshot','still respected']]),who('app','Приложение',['SELECT / UPDATE'])],[f('worker','orders','vacuum','internal'),f('app','orders','query')], '', 'Обслуживание расходует I/O и может ждать или уступать конфликтующей блокировке. Autovacuum никогда не запускает VACUUM FULL.','Maintenance consumes I/O and can wait for or yield to conflicting locks. Autovacuum never runs VACUUM FULL.'),
    s('Отдельные правила запускают ANALYZE, уборку вставок и защитную заморозку.','Separate rules trigger ANALYZE, insert-driven vacuum and protective freezing.',[tab('triggers','Разные причины','Different triggers',['work','reason'],[['VACUUM','obsolete / inserted'],['ANALYZE','changed rows'],['freeze','old transaction IDs']])],[], 'SELECT relname, last_autovacuum, last_autoanalyze FROM pg_stat_user_tables;', 'Порог мёртвых версий — не единственный. Защита от wraparound может запустить работу даже при отключённом обычном autovacuum.','Dead-version thresholds are not the only trigger. Wraparound protection may launch maintenance even when ordinary autovacuum is disabled.'),
  ]}),
  c({number:35,id:'freeze',group:4,title:['Старые строки и кольцо номеров','Old rows and the ID ring'],question:['Если строка живёт годами, её номер транзакции тоже остаётся безопасным?','If a row lives for years, does its transaction ID remain safe?'],next:['Заморозка защищает видимость. А почему файл всё ещё большой?','Freezing protects visibility. Why is the file still large?'],docs:['routine-vacuuming.html','storage-vm.html'],book:[125,137],steps:[
    s('Строка Alice остаётся живой, а сервер выполняет всё новые транзакции.','Alice remains live while the server executes ever more transactions.',[pg('heap',[['1','Alice','old committed xmin']])],[], '', 'Возраст строки не равен времени в часах: для защиты от wraparound важен возраст идентификаторов транзакций.','Row age is not elapsed clock time: wraparound protection concerns transaction-ID age.'),
    s('32-битные XID идут по кругу. Сравнивать их как бесконечно растущие числа нельзя.','32-bit XIDs wrap around. They cannot be compared as endlessly growing integers.',[a('ring','ring','Кольцо XID','XID ring',['32-bit IDs','past | current | future']),pg('heap',[['1','Alice','old committed xmin']])],[f('ring','heap','age increases','internal')], '', 'Сравнение использует круговой порядок с ограниченным безопасным горизонтом. Слишком старую вставку нужно пометить до потери этого порядка.','Comparison uses circular ordering with a bounded safe horizon. Very old insertions must be marked before that ordering becomes ambiguous.'),
    s('VACUUM проверяет старую подтверждённую вставку и помечает её замороженной.','VACUUM checks the old committed insertion and marks it frozen.',[box('vac','VACUUM','VACUUM',['committed + old enough']),pg('heap',[['1','Alice','xmin frozen']])],[f('vac','heap','freeze','internal')], 'VACUUM (FREEZE) users;', 'Заморозка означает, что вставка считается старше будущих снимков. Современный формат использует флаги; рисунок не обещает буквальную замену xmin на 2.','Freezing treats the insertion as older than future snapshots. Modern tuple formats use flags; the diagram does not promise a literal xmin replacement with 2.'),
    s('Когда заморожены все версии страницы, VM может поставить бит all-frozen.','When every tuple on a page is frozen, VM can set its all-frozen bit.',[pg('heap',[['1','Alice','frozen'],['2','Bob','frozen']]),tab('vm','Карта видимости','Visibility Map',['page','all-visible','all-frozen'],[['7','1','1']])],[f('heap','vm','verified page','internal')], '', 'All-frozen позволяет последующим защитным проходам пропустить страницу. Незамороженные либо ещё нужные версии нельзя объявить замороженными произвольно.','All-frozen lets later protective scans skip the page. Unfrozen or still-needed versions cannot be arbitrarily declared frozen.'),
    s('Замораживают и живые строки. Защитный VACUUM нельзя заменять только удалением мусора.','Live rows also need freezing. Protective VACUUM is more than garbage removal.',[tab('ages','Контроль возраста','Age monitoring',['object','measure'],[['XID','age(relfrozenxid)'],['MultiXact','mxid_age(relminmxid)']])],[], 'SELECT relname, age(relfrozenxid), mxid_age(relminmxid) FROM pg_class WHERE relkind = \'r\';', 'При опасном возрасте сервер требует обслуживания и в конце концов ограничивает новые операции. У MultiXact свой счётчик и свои границы.','At dangerous ages the server requires maintenance and eventually restricts new operations. MultiXact has its own counter and limits.'),
  ]}),
  c({number:36,id:'bloat',group:4,title:['Место свободно, а файл не уменьшился','Free space, unchanged file size'],question:['После VACUUM строк мало. Почему таблица всё ещё занимает много страниц?','Few rows remain after VACUUM. Why does the table still occupy many pages?'],next:['Сколько лишних страниц читает запрос? Посмотрим его план.','How many unnecessary pages does a query read? Let us inspect its plan.'],docs:['routine-vacuuming.html','sql-vacuum.html','sql-reindex.html','sql-cluster.html'],book:[170,180],steps:[
    s('После пика нагрузки живые строки остались на четырёх полупустых страницах.','After a workload peak, live rows remain spread across four partly empty pages.',[tab('heap','Разреженная таблица','Sparse table',['page','live','free'],[['0','Alice','large'],['1','Bob','large'],['2','Carol','large'],['3','Dan','large']])],[], "CREATE TABLE bloat_demo (id integer PRIMARY KEY, name text);\nINSERT INTO bloat_demo VALUES (1,'Alice'),(2,'Bob'),(3,'Carol'),(4,'Dan');", 'Bloat — избыточное размещение относительно полезных данных. Размер файла сам по себе не отличает мусор от намеренно свободного места.','Bloat is excessive storage relative to useful data. File size alone does not distinguish waste from intentional free space.'),
    s('Обычный VACUUM сделал промежутки пригодными для новых строк, но не пересобрал таблицу.','Ordinary VACUUM made gaps reusable without rewriting the table.',[tab('heap','Разреженная таблица','Sparse table',['page','live','free'],[['0','Alice','reusable'],['1','Bob','reusable'],['2','Carol','reusable'],['3','Dan','reusable']]),box('vac','VACUUM','VACUUM',['reuse, not full rewrite'])],[f('vac','heap','mark free','internal')], 'VACUUM bloat_demo;', 'Свободные внутренние страницы обычно остаются в файле. Пустой хвост — отдельный случай возможного обрезания.','Free interior pages normally remain in the file. An empty tail is a separate case where truncation may be possible.'),
    s('Новые строки заполняют промежутки. Для постоянной нагрузки это может быть полезным запасом.','New rows fill the gaps. A steady workload can use this space as useful headroom.',[tab('heap','Повторное использование','Reusing space',['page','live'],[['0','Alice, Eve'],['1','Bob, Finn'],['2','Carol'],['3','Dan']])],[], "INSERT INTO bloat_demo VALUES (5,'Eve'),(6,'Finn');", 'Уменьшать файл после каждого всплеска не обязательно: повторный рост тоже стоит I/O и блокировок. Оценивать нужно реальный доступ и устойчивый размер.','Shrinking after every burst is not necessarily useful: regrowth also costs I/O and locking. Evaluate actual access and steady-state size.'),
    s('VACUUM FULL переписывает все шесть живых строк плотнее и требует ACCESS EXCLUSIVE.','VACUUM FULL rewrites all six live rows compactly and requires ACCESS EXCLUSIVE.',[tab('heap','Старый файл','Old file',['page','live'],[['0','Alice, Eve'],['1','Bob, Finn'],['2','Carol'],['3','Dan']]),tab('new','Новый файл','New file',['page','live'],[['0','Alice, Bob'],['1','Carol, Dan'],['2','Eve, Finn']]),who('app','Приложение',['waiting'])],[f('heap','new','rewrite','internal'),f('app','heap','ACCESS SHARE','wait')], 'VACUUM (FULL) bloat_demo;', 'Состав строк сохраняется; размещение по страницам условное. Новая копия требует дополнительного места и блокировки; autovacuum не выполняет эту операцию.','All rows survive; page packing is illustrative. The new copy needs extra space and a lock; autovacuum never performs this operation.'),
    s('Таблица и индексы раздуваются отдельно. REINDEX перестраивает индекс, а не уплотняет heap.','Tables and indexes bloat separately. REINDEX rebuilds an index, not the heap.',[tab('choices','Разные инструменты','Different tools',['need','operation'],[['reuse heap space','VACUUM'],['rewrite heap','VACUUM FULL'],['rebuild index','REINDEX']])],[], 'REINDEX INDEX bloat_demo_pkey;', 'CLUSTER тоже переписывает таблицу, дополнительно выбирая порядок по индексу. Выбор требует учёта блокировок, места и последующего роста.','CLUSTER also rewrites a table and arranges it by an index. Choices depend on locking, free space and subsequent growth.'),
  ]}),
  c({number:37,id:'explain',group:5,title:['Почему запрос читает так много','Why a query reads so much'],question:['Приложению нужна одна строка. Как увидеть выбранный способ поиска?','The application needs one row. How can we see its chosen access path?'],next:['Как дерево индекса приводит прямо к нужной записи?','How does an index tree lead to the required entry?'],docs:['using-explain.html','sql-explain.html'],book:[319,345],steps:[
    s('Приложение ищет заказ 17. Снаружи видно только запрос и ответ.','The application looks for order 17. From outside, we see only a query and reply.',[who('app','Приложение',['WHERE id = 17'])],[], 'SELECT * FROM orders WHERE id = 17;', 'Один результат не означает одну прочитанную строку. Серверу ещё нужно выбрать способ найти её.','One result does not imply one row read. The server still needs to choose how to find it.'),
    s('EXPLAIN показывает план. В нашем учебном примере выбран последовательный просмотр.','EXPLAIN reveals the plan. Our illustrative case uses a sequential scan.',[who('app','Приложение',['EXPLAIN']),plan([['scan','Seq Scan on orders']],[]),box('filter','Свойство узла','Node property',['Filter: id = 17'])],[f('app','plan','EXPLAIN'),f('plan','app','estimated plan','reply')], 'EXPLAIN SELECT * FROM orders WHERE id = 17;', 'Рисунок — схема возможного плана, не сохранённый вывод сервера. На маленькой таблице Seq Scan может оказаться дешевле индекса.','This is a schematic possible plan, not captured server output. On a small table, Seq Scan can be cheaper than an index.'),
    s('Filter проверяет прочитанные строки. Оценка rows относится к выходу узла, а не ко всей прочитанной работе.','Filter checks fetched rows. Estimated rows describes node output, not all work scanned.',[plan([['scan','Seq Scan; filter id=17']],[]),tab('sample','Условный фрагмент','Illustrative fragment',['id','passes?'],[['15','no'],['16','no'],['17','yes'],['18','no']])],[f('plan','sample','inspect rows','internal')], '', 'Фильтр является свойством Seq Scan, а не обязательным отдельным узлом. Один выходной tuple может потребовать проверки множества кандидатов.','The filter is a Seq Scan property, not necessarily a separate node. One output tuple may require checking many candidates.'),
    s('cost — оценка работы. Начальное и полное значения не являются миллисекундами.','cost estimates work. Startup and total values are not milliseconds.',[tab('fields','Как читать оценку','Reading estimates',['field','meaning'],[['startup cost','before first row'],['total cost','complete node'],['rows','estimated output'],['width','estimated row bytes']])],[], '', 'Полная стоимость родителя включает работу потомков. Сравнивать нужно альтернативные планы для конкретного запроса, а не приравнивать cost к времени.','Parent total cost includes its children. Compare alternative plans for the query rather than equating cost with elapsed time.'),
    s('План объяснил способ поиска. Теперь откроем индекс и посмотрим, как он сокращает путь.','The plan explained the access path. Now open an index to see how it shortens the search.',[plan([['seq','Seq Scan'],['idx','Index Scan']],[ ]),box('choice','Два возможных пути','Two possible paths',['scan pages','or navigate index'])],[], '', 'Наличие индекса не заставляет планировщик использовать его. Сначала разберём сам механизм поиска, затем вернёмся к выбору плана.','An index does not force the planner to use it. First we examine navigation, then return to plan selection.'),
  ]}),
  c({number:38,id:'btree',group:5,title:['Найти ключ через B-tree','Finding a key through a B-tree'],question:['Как не проверять каждую строку ради id = 25?','How can id = 25 be found without checking every row?'],next:['Кто превращает SQL в такой путь и выбирает между путями?','Who transforms SQL into this path and chooses between alternatives?'],docs:['btree.html','indexes-types.html','indexes-ordering.html'],book:[523,554],steps:[
    s('Нужен id = 25. Построим индекс, в котором ключи ведут к адресам строк.','We need id = 25. Build an index whose keys lead to row addresses.',[who('app','Приложение',['id = 25'])],[], "CREATE TEMP TABLE btree_demo (id integer, name text);\nINSERT INTO btree_demo VALUES (1,'A'),(7,'B'),(12,'C'),(20,'D'),(25,'Alice'),(31,'F'),(40,'G'),(50,'H'),(70,'I');\nCREATE INDEX ON btree_demo (id);", 'Далее показано условное многоуровневое дерево. Маленькая настоящая таблица может разместить все записи на одной листовой странице.','The following multilevel tree is illustrative. A real tiny table might fit all entries on a single leaf page.'),
    s('Корень разделяет диапазоны: 25 относится к ветви от 20 до 40.','The root separates ranges: 25 belongs to the branch from 20 to 40.',[tree('idx','B-tree','B-tree',[['root','20 | 40'],['left','1 | 7 | 12'],['middle','20 | 25 | 31'],['right','40 | 50 | 70']],[['root','left'],['root','middle'],['root','right']]),who('app','Приложение',['20 <= 25 < 40'])],[f('app','idx','25')], 'SELECT name FROM btree_demo WHERE id = 25;', 'Внутренняя страница направляет на дочерние страницы. B-tree имеет много потомков, а не два, как бинарное дерево поиска.','An internal page points to child pages. A B-tree can have many children, unlike a binary search tree.'),
    s('На листе ключ 25 даёт TID. По нему читается версия Alice в heap.','At the leaf, key 25 gives a TID. It leads to Alice’s heap version.',[tree('idx','Лист индекса','Index leaf',[['leaf','25 -> TID (7,2)']],[]),pg('heap',[['1','id 20: D','live'],['2','id 25: Alice','visible']]),who('app','Приложение',['Alice'])],[f('idx','heap','(7,2)','internal'),f('heap','app','Alice','reply')], '', 'Обычный Index Scan проверяет видимость heap-версии. Совпадение ключа само по себе не доказывает видимость для снимка.','An ordinary Index Scan checks heap-tuple visibility. A matching key alone does not establish visibility to the snapshot.'),
    s('Диапазон 20…40 читается по соседним листовым записям: 20, 25, 31 и 40.','The range 20–40 follows neighboring leaf entries: 20, 25, 31 and 40.',[tree('idx','Соседние листья','Adjacent leaves',[['m','20 | 25 | 31'],['r','40 | 50 | 70']],[['m','r']]),tab('keys','Подходящие ключи','Matching keys',['id'],[['20'],['25'],['31'],['40']])],[f('idx','keys','range scan','internal')], 'SELECT id FROM btree_demo WHERE id BETWEEN 20 AND 40 ORDER BY id;', 'После поиска начала диапазона можно двигаться по листьям. Адреса соответствующих heap-строк при этом не обязаны находиться рядом.','After locating the range start, the scan can follow leaves. Corresponding heap rows need not be physically adjacent.'),
    s('Лист переполнен: вставка 30 делит его, а родитель получает новый переход.','A leaf is full: inserting 30 splits it and adds a new parent downlink.',[tree('idx','После разделения','After a split',[['root','20 | 30 | 40'],['l','1 | 7 | 12'],['m1','20 | 25'],['m2','30 | 31'],['r','40 | 50 | 70']],[['root','l'],['root','m1'],['root','m2'],['root','r']])],[], "INSERT INTO btree_demo VALUES (30,'New');", 'В рисунке вместимость листа условно равна трём записям. Реальная вместимость зависит от байтов; split может дойти до корня и добавить уровень.','The drawing gives leaves an illustrative three-entry capacity. Real capacity depends on bytes; a split can propagate to the root and add a level.'),
    s('ORDER BY id LIMIT 3 может остановиться после ключей 20, 25 и 30.','ORDER BY id LIMIT 3 can stop after keys 20, 25 and 30.',[tree('idx','Упорядоченный проход','Ordered traversal',[['m1','20 | 25'],['m2','30 | 31']],[['m1','m2']]),tab('keys','Результат','Result',['id'],[['20'],['25'],['30']])],[f('idx','keys','first 3','reply')], 'SELECT id FROM btree_demo WHERE id >= 20 ORDER BY id LIMIT 3;', 'B-tree умеет выдавать подходящий порядок, если выбран такой путь. SQL без ORDER BY порядка результата не обещает.','A chosen B-tree path can provide the requested order. SQL without ORDER BY does not promise result order.'),
  ]}),
  c({number:39,id:'query-path',group:5,title:['Как SQL становится работой','How SQL becomes work'],question:['Клиент прислал текст. Откуда появились узлы плана?','The client sent text. Where did the plan nodes come from?'],next:['Откуда планировщик знает, сколько строк найдётся?','How does the planner know how many rows will match?'],docs:['query-path.html','parser-stage.html','rule-system.html','planner-optimizer.html','executor.html','sql-prepare.html'],book:[319,345],steps:[
    s('Приложение просит имя пользователя 25. На входе это текст SQL.','The application asks for user 25’s name. The input is SQL text.',[who('app','Приложение',['SELECT name ...'])],[], 'SELECT name FROM btree_demo WHERE id = 25;', 'Проследим новый обычный SELECT. Служебные команды и повторное использование подготовленного плана могут идти иначе.','We follow a newly planned ordinary SELECT. Utility statements and reuse of prepared plans may follow different paths.'),
    s('Синтаксический разбор превращает текст в дерево: что выбрать, откуда и по какому условию.','Parsing turns text into a tree: what to select, from where, and under which condition.',[who('app','Приложение',['SQL text']),tree('parse','Синтаксическое дерево','Parse tree',[['q','SELECT'],['out','name'],['from','btree_demo'],['where','id = 25']],[['q','out'],['q','from'],['q','where']])],[f('app','parse','parse','internal')], '', 'На этом этапе проверяется грамматика. Слова ещё не являются выбранным алгоритмом Index Scan или Seq Scan.','This stage checks grammar. The words do not yet select an Index Scan or Seq Scan algorithm.'),
    s('Анализ связывает btree_demo, id и name с объектами каталога и определяет типы выражений.','Analysis binds btree_demo, id and name to catalog objects and determines expression types.',[tree('parse','Дерево запроса','Query tree',[['q','SELECT'],['t','btree_demo: relation'],['c','id: integer'],['e','= : integer equality']],[['q','t'],['q','c'],['q','e']]),box('catalog','Системный каталог','System catalog',['relations, columns, types'])],[f('parse','catalog','resolve names','internal')], '', 'Неизвестная таблица или несовместимые типы могут дать ошибку до планирования. Каталог придаёт тексту конкретный смысл.','Unknown relations or incompatible types may fail before planning. The catalog gives the text a concrete meaning.'),
    s('Переписывание раскрывает обычное представление в запрос к его исходным таблицам.','Rewriting expands an ordinary view into a query on its source tables.',[tree('rewrite','Переписанный запрос','Rewritten query',[['v','large_ids view'],['u','btree_demo'],['p','id >= 20']],[['v','u'],['v','p']])],[], "CREATE TEMP VIEW large_ids AS SELECT id, name FROM btree_demo WHERE id >= 20;\nSELECT name FROM large_ids WHERE id = 25;", 'Это отдельный пример с заранее определённым view. Обычное view не означает сохранённую копию результата; материализованные представления устроены иначе.','This separate example assumes an existing view. An ordinary view is not a stored result copy; materialized views are different.'),
    s('Планировщик сравнивает пути и строит план с конкретными сканами, соединениями и сортировками.','The planner compares paths and builds a plan with concrete scans, joins and sorts.',[box('paths','Возможные пути','Candidate paths',['Seq Scan','Index Scan']),plan([['i','Index Scan: id = 25']],[])],[f('paths','plan','estimated cheapest','internal')], '', 'Статистика, стоимость операций, доступные индексы и ограничения определяют выбор. Порядок слов SQL не задаёт буквальный порядок исполнения.','Statistics, operation costs, available indexes and constraints affect the choice. SQL word order is not a literal execution order.'),
    s('Исполнитель выполняет план и возвращает Alice. Подготовленный план иногда можно использовать повторно.','The executor runs the plan and returns Alice. A prepared plan can sometimes be reused.',[plan([['i','Index Scan on btree_demo']],[]),pg('heap',[['2','Alice','visible']]),who('app','Приложение',['Alice'])],[f('plan','heap','fetch','internal'),f('heap','app','Alice','reply')], '', 'Разбор, анализ, переписывание, планирование и исполнение — разные задачи. Повторный запрос не всегда требует заново выполнить каждую из них.','Parsing, analysis, rewriting, planning and execution are distinct tasks. A repeated query does not always repeat every task.'),
  ]}),
  c({number:40,id:'statistics',group:5,title:['Угадать число подходящих строк','Estimating matching rows'],question:['Как выбрать путь до того, как строки действительно прочитаны?','How can a path be chosen before reading the actual rows?'],next:['План выбран. Как его узлы передают друг другу строки?','The plan is chosen. How do its nodes exchange rows?'],docs:['planner-stats.html','sql-analyze.html','multivariate-statistics-examples.html'],book:[346,370],steps:[
    s('Из 1000 заказов 100 открыты. Поиск open затронет примерно десятую часть таблицы.','Of 1000 orders, 100 are open. Searching for open touches roughly a tenth of the table.',[tab('distribution','Распределение статусов','Status distribution',['status','rows'],[['open','100'],['closed','900']])],[], "CREATE TEMP TABLE orders_stats (id integer, status text);\nINSERT INTO orders_stats SELECT i, CASE WHEN i <= 100 THEN 'open' ELSE 'closed' END FROM generate_series(1,1000) AS g(i);\nSELECT * FROM orders_stats WHERE status = 'open';", 'Это полный состав учебного примера. Планировщик обычно узнаёт распределение по статистике, а не считает строки перед каждым SELECT.','This is the complete illustrative distribution. The planner normally uses statistics instead of counting rows before every SELECT.'),
    s('ANALYZE собирает выборку и запоминает частые значения, доли NULL и другие оценки.','ANALYZE samples data and records common values, NULL fractions and other estimates.',[tab('distribution','Распределение статусов','Status distribution',['status','rows'],[['open','100'],['closed','900']]),tab('stats','Учебная статистика','Illustrative statistics',['field','value'],[['reltuples','about 1000'],['open frequency','about 0.10']])],[f('distribution','stats','ANALYZE','internal')], 'ANALYZE orders_stats;', 'Для значений вне списка частых используются другие сведения, включая гистограммы и число различных значений. Оценки не обязаны быть точными.','Values outside common-value lists use other information, including histograms and distinct counts. Estimates need not be exact.'),
    s('Доля 0,10 даёт оценку около 100 выходных строк. Это влияет на цену скана и соединения.','A 0.10 fraction predicts about 100 output rows. This affects scan and join costs.',[tab('stats','Учебная статистика','Illustrative statistics',['rows','fraction'],[['1000','0.10']]),box('estimate','Оценка результата','Output estimate',['1000 x 0.10 = 100'])],[f('stats','estimate','selectivity','internal')], 'EXPLAIN SELECT * FROM orders_stats WHERE status = \'open\';', 'Rows в EXPLAIN — ожидание планировщика. Оно может повлиять и на планы следующих узлов, которые получают результат скана.','Rows in EXPLAIN is a planner expectation. It also affects downstream nodes that consume the scan output.'),
    s('Теперь открыты 900 заказов, а статистика помнит 100. Повторный ANALYZE исправляет исходные сведения.','Now 900 orders are open, but statistics remembers 100. ANALYZE refreshes the inputs.',[tab('distribution','Новые данные','Changed data',['status','rows'],[['open','900'],['closed','100']]),tab('stats','После ANALYZE','After ANALYZE',['open frequency','estimate'],[['about 0.90','about 900']])],[f('distribution','stats','refresh sample','internal')], "UPDATE orders_stats SET status = CASE WHEN id <= 900 THEN 'open' ELSE 'closed' END;\nANALYZE orders_stats;", 'Свежая статистика улучшает оценку, но не гарантирует идеальный план. Рисунок округляет значения выборки для объяснения.','Fresh statistics improve estimates without guaranteeing a perfect plan. The drawing rounds sampled estimates for clarity.'),
    s('Город связан со страной. Расширенная статистика помогает не считать такие условия независимыми.','City depends on country. Extended statistics can avoid treating these conditions as independent.',[tab('related','Связанные столбцы','Related columns',['city','country'],[['Paris','FR'],['Lyon','FR'],['Berlin','DE']]),box('dependency','Зависимость','Dependency',['city -> country'])],[f('related','dependency','sample jointly','internal')], "CREATE TEMP TABLE customer_geography (city text, country text);\nINSERT INTO customer_geography VALUES ('Paris','FR'),('Lyon','FR'),('Berlin','DE');\nCREATE STATISTICS city_country_stats (dependencies) ON city, country FROM customer_geography;\nANALYZE customer_geography;", 'Это отдельный пример. Dependencies, MCV и ndistinct решают разные задачи и не делают все оценки, в частности оценки соединений, точными.','This is a separate example. Dependencies, MCV and ndistinct serve different purposes and do not make every estimate, particularly join estimates, exact.'),
  ]}),
  c({number:41,id:'executor',group:5,title:['Строки поднимаются по плану','Rows move up the plan'],question:['Кто первым начинает работу: скан внизу или LIMIT наверху?','Who starts the work: the scan below or LIMIT above?'],next:['Как сравнить ожидаемую работу плана с выполненной?','How can expected plan work be compared with actual execution?'],docs:['executor.html','using-explain.html'],book:[319,345],steps:[
    s('Нужны первые два счёта с балансом больше 10. LIMIT просит дочерний узел дать строку.','We need two accounts with balance above 10. LIMIT asks its child for a row.',[plan([['limit','Limit: 2'],['scan','Seq Scan: balance > 10']],[['limit','scan']])],[], "CREATE TEMP TABLE executor_accounts (id integer PRIMARY KEY, balance integer);\nINSERT INTO executor_accounts VALUES (1,5),(2,20),(3,30),(4,40);\nSELECT id FROM executor_accounts WHERE balance > 10 LIMIT 2;", 'Исполнение — pull-модель: запрос следующей строки идёт сверху вниз, а найденная строка возвращается вверх.','Execution is demand-pull: next-row requests travel downward, and resulting rows travel upward.'),
    s('Скан проверяет счёт 1: баланс 5 не подходит. Он продолжает поиск для того же запроса LIMIT.','The scan checks account 1: balance 5 fails. It keeps searching for the same LIMIT request.',[plan([['limit','needs output row 1'],['scan','Seq Scan: reject id 1']],[['limit','scan']]),tab('heap','Счета в учебном порядке','Accounts in example order',['id','balance'],[['1','5'],['2','20'],['3','30'],['4','40']])],[f('plan','heap','next tuple','internal')], '', 'Строка, отброшенная фильтром, не считается выходной строкой скана. LIMIT пока ничего не получил.','A filtered-out tuple is not a scan output row. LIMIT has received nothing yet.'),
    s('Счёт 2 подходит. Скан возвращает его вверх, и LIMIT получает первый результат.','Account 2 qualifies. The scan returns it upward, giving LIMIT its first result.',[plan([['limit','received 1 of 2'],['scan','Seq Scan: id 2']],[['limit','scan']]),tab('heap','Счета в учебном порядке','Accounts in example order',['id','balance'],[['1','5'],['2','20'],['3','30'],['4','40']]),tab('result','Результат','Result',['id'],[['2']])],[f('heap','plan','id 2','internal'),f('plan','result','row 1','reply')], '', 'Каждый вызов узла должен вернуть следующую строку либо признак окончания. Один вызов может потребовать проверки многих входных строк.','Each node call returns its next row or end-of-input. One call can require inspecting many input rows.'),
    s('Следующий запрос даёт счёт 3. LIMIT набрал две строки и больше не просит; счёт 4 не нужен.','The next request yields account 3. LIMIT has two rows and stops asking; account 4 is unnecessary.',[plan([['limit','2 of 2: stop'],['scan','no further request']],[['limit','scan']]),tab('result','Результат','Result',['id'],[['2'],['3']]),box('unread','Не прочитано в примере','Unread in this example',['id 4'])],[], '', 'Без ORDER BY это лишь один допустимый порядок посещения, а не обещание всегда выбрать id 2 и 3.','Without ORDER BY this is one valid visitation order, not a promise to always choose IDs 2 and 3.'),
    s('Добавили ORDER BY balance DESC: Sort должен просмотреть вход, прежде чем отдать самый большой баланс.','Add ORDER BY balance DESC: Sort must inspect its input before returning the greatest balance.',[plan([['limit','Limit: 2'],['sort','Sort: balance DESC'],['scan','Seq Scan']],[['limit','sort'],['sort','scan']]),tab('result','Результат','Result',['id','balance'],[['4','40'],['3','30']])],[f('plan','result','4, 3','reply')], 'SELECT id, balance FROM executor_accounts WHERE balance > 10 ORDER BY balance DESC LIMIT 2;', 'Sort — блокирующий этап. Top-N может хранить только лучшие кандидаты, но всё равно должен проверить весь подходящий вход.','Sort is a blocking stage. Top-N can retain only the best candidates while still inspecting the entire qualifying input.'),
  ]}),
  c({number:42,id:'explain-analyze',group:5,title:['План ожидал — запрос сделал','Expected plan, actual work'],question:['Оценка выглядит разумно. Совпала ли она с действительностью?','The estimate looks reasonable. Did execution agree?'],next:['Почему Sort или Hash вдруг начали писать временные файлы?','Why did Sort or Hash start writing temporary files?'],docs:['using-explain.html','sql-explain.html','sql-analyze.html'],book:[319,345],steps:[
    s('Обычный EXPLAIN описывает ожидаемые строки. Запрос при этом не выполняется.','Plain EXPLAIN describes expected rows without executing the query.',[plan([['join','Nested Loop: estimate'],['outer','customers: 3 rows'],['inner','orders: 2 per customer']],[['join','outer'],['join','inner']])],[], "CREATE TEMP TABLE plan_customers (id integer PRIMARY KEY);\nINSERT INTO plan_customers VALUES (1),(2),(3);\nCREATE TEMP TABLE plan_orders (id integer, customer_id integer, status text);\nINSERT INTO plan_orders SELECT i, ((i-1)/2)+1, 'ready' FROM generate_series(1,6) AS g(i);\nCREATE INDEX ON plan_orders (customer_id);\nEXPLAIN SELECT c.id, o.id FROM plan_customers c JOIN plan_orders o ON o.customer_id = c.id WHERE c.id BETWEEN 1 AND 3;", 'План на рисунке условный. Оценки ещё не являются измерением времени, фактических строк или вызовов.','The displayed plan is illustrative. Estimates are not measured timing, actual rows or invocation counts.'),
    s('EXPLAIN ANALYZE запускает запрос и добавляет фактические строки, время и loops.','EXPLAIN ANALYZE runs the query and adds actual rows, timing and loops.',[plan([['join','Nested Loop: rows=6'],['outer','rows=3 loops=1'],['inner','rows=2 loops=3']],[['join','outer'],['join','inner']]),box('run','Учебный профиль','Illustrative profile',['query executed'])],[], 'EXPLAIN (ANALYZE, BUFFERS) SELECT c.id, o.id FROM plan_customers c JOIN plan_orders o ON o.customer_id = c.id WHERE c.id BETWEEN 1 AND 3;', 'Числа показывают согласованный учебный профиль, не проведённый здесь замер. В данном примере у каждого из трёх клиентов ровно два заказа.','These numbers form a consistent illustrative profile, not a measurement performed here. Each of the three customers has exactly two orders in this example.'),
    s('rows = 2, loops = 3 означает в среднем две строки за запуск: всего шесть.','rows = 2, loops = 3 means two rows per execution on average: six in total.',[tab('loops','Среднее и итог','Average and total',['field','value'],[['actual rows','2 per execution'],['loops','3'],['total output','2 x 3 = 6']])],[], '', 'Фактическое время узла тоже усредняется по loops. Стоимости и время родителей включают работу детей: складывать все строки плана как независимые нельзя.','Node actual times are also averaged across loops. Parent costs and times include child work; plan lines cannot be summed as independent operations.'),
    s('BUFFERS различает shared-блоки обычных таблиц, local-блоки временных таблиц и temp-файлы промежуточной работы.','BUFFERS distinguishes shared blocks of regular tables, local blocks of temporary tables, and temporary spill files.',[tab('buffers','Смысл счётчиков','Counter meanings',['field','meaning'],[['shared hit/read','regular tables'],['local hit/read','temporary tables'],['temp read/write','spill files']])],[], '', 'Наши TEMP-таблицы используют local-блоки; temp read/write означает промежуточные файлы. Shared read может обслужить кеш ОС. Счётчики родителя включают детей и повторы; ANALYZE включает BUFFERS автоматически.','Our TEMP tables use local blocks; temp read/write means intermediate files. Shared reads may hit the OS cache. Parent counts include children and repeats; ANALYZE automatically includes BUFFERS.'),
    s('С ANALYZE команда UPDATE действительно меняет строки и запускает триггеры.','With ANALYZE, UPDATE really changes rows and runs triggers.',[tab('orders','Изменяемые строки','Rows being changed',['id','status'],[['1','archived'],['2','archived']]),seq('transaction','Проверка с откатом','Inspection with rollback',['BEGIN','EXPLAIN ANALYZE UPDATE','ROLLBACK'])],[f('transaction','orders','execute UPDATE','internal')], "BEGIN;\nEXPLAIN (ANALYZE, BUFFERS) UPDATE plan_orders SET status = 'archived' WHERE id <= 2;\nROLLBACK;", 'Откат возвращает транзакционные изменения таблиц. Он не отменяет любые внешние эффекты или расход значений sequence, если их вызвал запрос.','Rollback restores transactional table changes. It does not undo arbitrary external effects or sequence values consumed by the query.'),
    s('ANALYZE orders — другая команда: она собирает статистику, а не измеряет SELECT.','ANALYZE orders is different: it gathers statistics rather than measuring a SELECT.',[tab('commands','Три разных действия','Three different actions',['command','action'],[['EXPLAIN','estimate plan'],['EXPLAIN ANALYZE','run and measure'],['ANALYZE table','sample statistics']])],[], 'ANALYZE plan_orders;', 'Сравнивайте оценки с фактом, проверяйте loops и объём входа. EXPLAIN ANALYZE добавляет собственную измерительную нагрузку, поэтому время не равно чистому пользовательскому запросу.','Compare estimates with actuals, checking loops and input volume. EXPLAIN ANALYZE adds instrumentation overhead, so its timing differs from an uninstrumented request.'),
  ]}),
  c({number:43,id:'work-mem',group:5,title:['Когда промежуточным данным тесно','When intermediate data outgrow memory'],question:['Данные прочитаны. Где хранятся строки сортировки и хеш-таблицы?','Data has been read. Where do sort rows and hash tables live?'],next:['Теперь объединим строки двух таблиц и проследим их результат.','Now combine rows from two tables and trace the result.'],docs:['runtime-config-resource.html','using-explain.html'],book:[483,508],steps:[
    s('Sort должен упорядочить больше строк, чем помещается в его рабочей памяти.','Sort must order more rows than fit in its working memory.',[plan([['sort','Sort: ORDER BY id DESC'],['scan','Seq Scan: many rows']],[['sort','scan']]),box('memory','Рабочая память','Working memory',['work_mem = 4 MB'])],[f('plan','memory','sort input','internal')], "SET work_mem = '4MB';\nCREATE TEMP TABLE sort_demo AS SELECT i AS id, repeat('x',200) AS payload FROM generate_series(1,50000) AS g(i);\nSELECT * FROM sort_demo ORDER BY id DESC;", 'work_mem относится к отдельной операции, например сортировке, а не ко всей базе и не к общему кешу страниц.','work_mem applies to an operation such as a sort, not the entire database or the shared page cache.'),
    s('Sort записывает отсортированные порции во временные файлы, затем сливает их.','Sort writes sorted runs to temporary files and then merges them.',[box('memory','Рабочая память','Working memory',['current run']),seq('temp','Временные порции','Temporary runs',['run A: sorted','run B: sorted','merge runs'])],[f('memory','temp','spill runs','internal')], '', 'Spill — переход к внешнему алгоритму, а не ошибка запроса. В плане могут появиться external merge и объём Disk.','Spilling switches to an external algorithm rather than failing the query. The plan may show external merge and disk usage.'),
    s('Hash может делить работу на batches. Его предел связан с work_mem и hash_mem_multiplier.','Hash may split work into batches. Its limit depends on work_mem and hash_mem_multiplier.',[box('memory','Явные настройки','Explicit settings',['work_mem = 4 MB','hash multiplier = 2']),bucket(['batch 1','batch 2 on temp file'])],[f('memory','hash','hash budget: 8 MB','internal')], "SET work_mem = '4MB';\nSET hash_mem_multiplier = 2;", 'В учебных настройках хеш-операция ориентируется на 8 MB. Реальный расход включает накладные данные; work_mem не является строгим пределом всей памяти процесса.','With these settings, a hash operation targets 8 MB. Actual usage includes overhead; work_mem is not a strict cap on all process memory.'),
    s('Две сортировки в одном плане могут получить собственные бюджеты. У соседнего запроса — свои.','Two sorts in one plan can each receive a budget. Another query has its own budgets.',[tab('budgets','Несколько операций','Several operations',['session','operation','base budget'],[['A','sort 1','4 MB'],['A','sort 2','4 MB'],['B','sort 1','4 MB']])],[], '', 'Несколько одновременно работающих узлов и сессий умножают потребление. Параллельные workers тоже могут иметь собственные лимиты.','Concurrent nodes and sessions multiply memory demand. Parallel workers can also have their own limits.'),
    s('Увеличение памяти может убрать spill. Но решение проверяют по плану и общей нагрузке.','More memory may remove a spill. Verify it against the plan and overall workload.',[tab('check','Что проверять','What to inspect',['operation','evidence'],[['Sort','method; memory/disk'],['Hash','batches; memory'],['whole server','concurrent work']])],[], "BEGIN;\nSET LOCAL work_mem = '16MB';\nEXPLAIN (ANALYZE, BUFFERS) SELECT * FROM sort_demo ORDER BY id DESC;\nROLLBACK;", 'Сравнение должно использовать одинаковые данные и учитывать кеши. Увеличение work_mem не обещает ускорение и не заменяет удачный план.','Use the same data and account for caches when comparing. Raising work_mem does not guarantee a speedup or replace a good plan.'),
  ]}),
  c({number:44,id:'inner-join',group:6,title:['Собрать все совпадающие пары','Construct every matching pair'],question:['В двух таблицах есть одинаковый ключ. Сколько строк даст соединение?','Two tables share a key. How many rows does their join produce?'],next:['Что делать со строкой, у которой не нашлось пары?','What happens to a row that finds no partner?'],docs:['queries-table-expressions.html','queries-select-lists.html'],book:[438,456],steps:[
    s('L1 и L2 — разные строки с одним ключом 1. Нельзя заранее слить их в одну.','L1 and L2 are separate rows sharing key 1. They must not be collapsed into one.',[joinL()],[],joinSetup, 'rid различает строки, k служит условием соединения. SQL сохраняет повторения, если запрос явно не требует DISTINCT.','rid identifies rows while k supplies the join condition. SQL preserves duplicates unless the query explicitly requests DISTINCT.'),
    s('У L1 нашлась R1 с тем же ключом. Первая пара — L1 + R1.','L1 finds R1 with the same key. The first pair is L1 + R1.',[joinL(),joinR(),pairs([['L1','R1']])],[f('left','right','k = 1','internal'),f('right','result','L1 + R1','internal')], 'SELECT l.rid, r.rid FROM join_l l INNER JOIN join_r r ON l.k = r.k ORDER BY l.rid, r.rid;', 'Мы строим результат по частям, не показываем физический алгоритм. INNER JOIN включает каждую пару, для которой ON равно true.','We build the result incrementally, without selecting a physical algorithm. INNER JOIN includes each pair whose ON condition is true.'),
    s('R2 тоже подходит L1. Поэтому L1 участвует уже в двух выходных строках.','R2 also matches L1, so L1 participates in two output rows.',[joinL(),joinR(),pairs([['L1','R1'],['L1','R2']])],[f('right','result','L1 + R2','internal')], '', 'Соединение не выбирает единственную «лучшую» пару и не останавливается на первом совпадении.','The join does not pick one best partner or stop after its first match.'),
    s('L2 тоже имеет ключ 1 и образует пары с R1 и R2. Две строки на две дают четыре пары.','L2 also has key 1 and pairs with R1 and R2. Two rows times two yields four pairs.',[joinL(),joinR(),pairs(matched)],[f('left','right','L2: k = 1','internal'),f('right','result','two more pairs','internal')], '', 'Даже если SELECT выводит только k, получится четыре одинаковых значения 1. DISTINCT — отдельное преобразование результата.','Even SELECT of k alone produces four copies of 1. DISTINCT is a separate result transformation.'),
    s('У L3 ключ 2, а у R3 — 3. Новых совпадающих пар нет; INNER JOIN возвращает четыре строки.','L3 has key 2 and R3 has key 3. Neither adds a match; INNER JOIN returns four rows.',[joinL(),joinR(),pairs(matched)],[f('left','right','2 != 1, 3','internal')], 'SELECT count(*) FROM join_l l INNER JOIN join_r r ON l.k = r.k;', 'Диаграмма показывает конкретные пары строк, а не пересечение двух множеств уникальных ключей. Это сохраняет кратность результата.','The diagram shows actual row pairs, not an intersection of unique-key sets. This preserves result multiplicity.'),
    s('CROSS JOIN не требует совпадения: каждая из трёх левых строк сочетается с каждой правой. Всего девять.','CROSS JOIN needs no match: each of three left rows pairs with each right row. Total: nine.',[joinL(),joinR(),box('count','Декартово произведение','Cartesian product',['3 x 3 = 9 pairs'])],[f('left','count','3 rows','internal'),f('right','count','3 rows','internal')], 'SELECT count(*) FROM join_l CROSS JOIN join_r;', 'Это другой запрос. CROSS JOIN равносилен INNER JOIN ON TRUE, но не снимает ограничения типов и имён обычных выражений.','This is a different query. CROSS JOIN is equivalent to INNER JOIN ON TRUE.'),
  ]}),
  c({number:45,id:'outer-join',group:6,title:['Не потерять строку без пары','Keep an unmatched row'],question:['Нужны все клиенты, даже если у некоторых нет заказов.','We need every customer, including those without orders.'],next:['NULL в исходных данных и NULL от отсутствующей пары — как они влияют на условие?','How do source NULLs and NULLs from missing partners affect the condition?'],docs:['queries-table-expressions.html'],book:[438,456],steps:[
    s('L3 с ключом 2 исчезла из INNER JOIN. Теперь хотим сохранить каждую левую строку.','L3 with key 2 disappeared from INNER JOIN. Now preserve every left row.',[joinL()],[], joinSetup, 'LEFT относится к положению таблицы в выражении JOIN. Одинаковый ключ может по-прежнему давать несколько пар.','LEFT refers to the table position in the JOIN expression. A shared key can still produce multiple pairs.'),
    s('Сначала строятся те же четыре совпадающие пары ключа 1.','First construct the same four matching pairs for key 1.',[joinL(),joinR(),pairs(matched)],[f('left','right','matching pairs','internal'),f('right','result','4 pairs','internal')], 'SELECT l.rid, r.rid FROM join_l l LEFT JOIN join_r r ON l.k = r.k ORDER BY l.rid, r.rid;', 'Это объяснение логического результата; физический план не обязан сначала материализовать промежуточный INNER JOIN.','This explains the logical result. The physical plan need not materialize an intermediate INNER JOIN.'),
    s('Для L3 совпадений нет. LEFT JOIN добавляет одну строку L3 + NULL: итог — пять.','L3 has no match. LEFT JOIN adds one L3 + NULL row, making five rows.',[joinL(),joinR(),pairs([...matched,['L3','NULL']])],[f('left','result','L3 + NULL','internal')], '', 'NULL заполняет все выходные столбцы отсутствующей правой строки. Это не найденная в правой таблице строка с пустыми значениями.','NULL fills every output column of the missing right row. It is not a stored right-table row containing empty values.'),
    s('RIGHT JOIN сохраняет правую сторону: вместо L3 добавится NULL + R3. Тоже пять строк.','RIGHT JOIN preserves the right side: NULL + R3 replaces the extra L3 row. Again five rows.',[joinL(),joinR(),pairs([...matched,['NULL','R3']])],[f('right','result','NULL + R3','internal')], 'SELECT l.rid, r.rid FROM join_l l RIGHT JOIN join_r r ON l.k = r.k ORDER BY l.rid NULLS LAST, r.rid;', 'Несовпавшая левая L3 для RIGHT JOIN не сохраняется. Совпавшие четыре пары остаются теми же.','RIGHT JOIN does not preserve the unmatched left L3. The four matching pairs remain unchanged.'),
    s('FULL JOIN сохраняет обе стороны: четыре пары, L3 + NULL и NULL + R3. Всего шесть строк.','FULL JOIN preserves both sides: four pairs, L3 + NULL and NULL + R3. Six rows in total.',[pairs(matched),tab('unmatched','Без пары','Unmatched rows',['left.rid','right.rid'],[['L3','NULL'],['NULL','R3']]),box('count','Итог FULL JOIN','FULL JOIN total',['4 + 1 + 1 = 6'])],[], 'SELECT l.rid, r.rid FROM join_l l FULL JOIN join_r r ON l.k = r.k ORDER BY l.rid NULLS LAST, r.rid;', 'Две таблицы на рисунке — две группы одного результата. Повторяющиеся ключи не исчезают при переходе к FULL JOIN.','The two displayed tables are groups within one result. Duplicate keys do not disappear in a FULL JOIN.'),
    s('Поменяли стороны местами: join_r LEFT JOIN join_l сохраняет R3, как прежний RIGHT JOIN.','Swap the inputs: join_r LEFT JOIN join_l preserves R3, like the previous RIGHT JOIN.',[tab('right','Теперь слева: join_r','Now left: join_r',['rid','k'],[['R1','1'],['R2','1'],['R3','3']]),pairs([...matched,['NULL','R3']])],[f('right','result','preserve R3','internal')], 'SELECT l.rid, r.rid FROM join_r r LEFT JOIN join_l l ON l.k = r.k ORDER BY l.rid NULLS LAST, r.rid;', 'Сравниваем одинаково перечисленные выходные столбцы l.rid и r.rid. Направление сохранения — семантика JOIN, а не выбор Hash или Nested Loop.','We compare the same output columns, l.rid and r.rid. Preservation direction is JOIN semantics, not a Hash versus Nested Loop choice.'),
  ]}),
  c({number:46,id:'join-nulls',group:6,title:['NULL не совпадает сам с собой','NULL does not equal itself'],question:['Две строки содержат NULL. Они образуют пару по знаку равенства?','Two rows contain NULL. Do they match using equality?'],next:['А если нужны только строки, у которых существует хотя бы одна пара?','What if only rows with at least one partner are needed?'],docs:['queries-table-expressions.html','functions-comparison.html'],book:[438,456],steps:[
    s('Слева L1 с ключом 1 и L2 с NULL. Справа — R1 с 1 и R2 с NULL.','The left has L1 with key 1 and L2 with NULL. The right has R1 with 1 and R2 with NULL.',[tab('left','Левая таблица','Left table',['rid','k'],[['L1','1'],['L2','NULL']]),tab('right','Правая таблица','Right table',['rid','k'],[['R1','1'],['R2','NULL']])],[], "CREATE TEMP TABLE null_l (rid text, k integer);\nINSERT INTO null_l VALUES ('L1',1),('L2',NULL);\nCREATE TEMP TABLE null_r (rid text, k integer);\nINSERT INTO null_r VALUES ('R1',1),('R2',NULL);", 'NULL — отсутствие известного значения, а не строка "NULL", ноль или пустая строка.','NULL represents an unknown value, not the text "NULL", zero or an empty string.'),
    s('1 = 1 даёт true. NULL = NULL даёт unknown, поэтому L2 и R2 не совпадают.','1 = 1 is true. NULL = NULL is unknown, so L2 and R2 do not match.',[tab('tests','Результат сравнения','Comparison results',['expression','result'],[['1 = 1','true'],['NULL = NULL','unknown']]),pairs([['L1','R1']])],[f('tests','result','true only','internal')], 'SELECT l.rid, r.rid FROM null_l l JOIN null_r r ON l.k = r.k;', 'Условие ON принимает пару только при true. И false, и unknown означают, что эта пара не подходит.','ON accepts a pair only when true. Both false and unknown reject the pair.'),
    s('LEFT JOIN сохраняет L2, но заполняет её правую часть NULL. Это не совпадение с R2.','LEFT JOIN preserves L2 and null-extends its right side. This is not a match with R2.',[tab('right','Правая таблица','Right table',['rid','k'],[['R1','1'],['R2','NULL']]),pairs([['L1','R1'],['L2','NULL']])],[], 'SELECT l.rid, r.rid FROM null_l l LEFT JOIN null_r r ON l.k = r.k ORDER BY l.rid;', 'Правый rid различает сохранённую без пары строку и реально совпавшую строку R2. Пустые ячейки интерфейса часто скрывают эту разницу.','The right rid distinguishes an unmatched preserved row from an actual R2 match. Blank UI cells often obscure this difference.'),
    s('Условие r.k = 2 в ON оставит две левые строки с NULL. То же условие в WHERE удалит обе.','Putting r.k = 2 in ON keeps two null-extended left rows. Putting it in WHERE removes both.',[tab('on','Фильтр внутри ON','Condition inside ON',['left.rid','right.rid'],[['L1','NULL'],['L2','NULL']]),tab('where','Фильтр после JOIN','Condition after JOIN',['left.rid','right.rid'],[])],[], 'SELECT l.rid, r.rid FROM null_l l LEFT JOIN null_r r ON l.k = r.k AND r.k = 2;\nSELECT l.rid, r.rid FROM null_l l LEFT JOIN null_r r ON l.k = r.k WHERE r.k = 2;', 'ON решает, какие пары подходят до сохранения левой стороны. WHERE проверяет уже полученные строки; unknown не проходит этот фильтр.','ON determines matching pairs before left-side preservation. WHERE filters the resulting rows; unknown does not pass it.'),
    s('IS NOT DISTINCT FROM явно выбирает NULL-безопасное сравнение: теперь L2 совпадает с R2.','IS NOT DISTINCT FROM explicitly chooses NULL-safe comparison: L2 now matches R2.',[pairs([['L1','R1'],['L2','R2']]),box('condition','Другое условие','A different condition',['NULL IS NOT DISTINCT','FROM NULL -> true'])],[], 'SELECT l.rid, r.rid FROM null_l l JOIN null_r r ON l.k IS NOT DISTINCT FROM r.k ORDER BY l.rid;', 'Это сознательно другая семантика условия. Она не меняет обычное равенство и не делает все операции с NULL двузначными.','This deliberately changes the condition semantics. It does not alter ordinary equality or turn every NULL operation into two-valued logic.'),
  ]}),
  c({number:47,id:'exists',group:6,title:['Нужен факт существования, а не все пары','Existence rather than every pair'],question:['Как найти клиентов с заказами, не размножая каждого по числу заказов?','How can customers with orders be found without multiplying them by order count?'],next:['Теперь результат понятен. Каким алгоритмом получать пары?','The result is clear. Which algorithm should produce its pairs?'],docs:['functions-subquery.html','queries-table-expressions.html'],book:[438,456],steps:[
    s('L1 и L2 имеют ключ 1. Нам нужны сами эти строки, если справа есть хоть одно совпадение.','L1 and L2 have key 1. We need those rows themselves if any right-side match exists.',[joinL()],[],joinSetup, 'Задача отличается от получения всех пар INNER JOIN. Повторы исходных левых строк при этом тоже не следует автоматически удалять.','This differs from returning every INNER JOIN pair. Existing duplicate left rows should not be automatically removed either.'),
    s('EXISTS включает L1 и L2 по одному разу каждую. Два правых совпадения не удваивают их снова.','EXISTS includes L1 and L2 once each. Two right matches do not multiply them again.',[joinL(),joinR(),tab('result','Результат EXISTS','EXISTS result',['rid','k'],[['L1','1'],['L2','1']])],[f('left','right','any match?','internal'),f('right','result','L1, L2','internal')], 'SELECT l.rid, l.k FROM join_l l WHERE EXISTS (SELECT 1 FROM join_r r WHERE r.k = l.k) ORDER BY l.rid;', 'Проверке достаточно факта совпадения; планировщик может использовать semi join. Это не SELECT DISTINCT после большого набора пар.','Only existence matters; the planner may use a semi join. This is not DISTINCT applied after constructing a large pair set.'),
    s('NOT EXISTS оставляет L3: у ключа 2 нет ни одной пары.','NOT EXISTS keeps L3: key 2 has no partner.',[joinL(),joinR(),tab('result','Результат NOT EXISTS','NOT EXISTS result',['rid','k'],[['L3','2']])],[f('left','right','no match?','internal'),f('right','result','L3','internal')], 'SELECT l.rid, l.k FROM join_l l WHERE NOT EXISTS (SELECT 1 FROM join_r r WHERE r.k = l.k);', 'Anti join отвечает «совпадений нет», сохраняя кратность левого входа. Это не удаление строк из таблицы.','An anti join asks whether no match exists and preserves left-input multiplicity. It does not delete table rows.'),
    s('Добавили NULL справа. Теперь k NOT IN (...) не вернёт даже L3: для 2 ответ unknown.','Add a right-side NULL. Now k NOT IN (...) does not return L3 either: for 2 it is unknown.',[joinL(),tab('right','Правая таблица с NULL','Right table with NULL',['rid','k'],[['R1','1'],['R2','1'],['R3','3'],['R4','NULL']]),tab('result','Результат NOT IN','NOT IN result',['rid','k'],[])],[], "INSERT INTO join_r VALUES ('R4',NULL);\nSELECT rid, k FROM join_l WHERE k NOT IN (SELECT k FROM join_r);", 'При отсутствии равного значения NULL внутри списка не позволяет получить true для NOT IN. NOT EXISTS с прежним условием всё ещё вернёт L3.','Without an equal value, a NULL in the list prevents NOT IN from becoming true. NOT EXISTS with the earlier condition still returns L3.'),
    s('Исключили NULL справа — для наших ненулевых левых ключей NOT IN снова возвращает L3.','Remove right-side NULLs: for our non-NULL left keys, NOT IN returns L3 again.',[tab('right','Ненулевые ключи','Non-NULL keys',['k'],[['1'],['1'],['3']]),tab('result','Результат','Result',['rid','k'],[['L3','2']])],[], 'SELECT rid, k FROM join_l WHERE k NOT IN (SELECT k FROM join_r WHERE k IS NOT NULL);', 'Равенство с NOT EXISTS здесь зависит от ненулевых левых ключей. Если слева тоже есть NULL, нужно отдельно определить желаемую семантику.','Equivalence with NOT EXISTS here relies on non-NULL left keys. If the left also contains NULL, define the intended semantics separately.'),
  ]}),
  c({number:48,id:'nested-loop',group:6,title:['Для каждой строки найти её пары','Find matches for each input row'],question:['Как исполнитель получает знакомый результат JOIN по одной паре?','How does the executor produce the familiar JOIN result one pair at a time?'],next:['Можно ли подготовить правую сторону один раз вместо повторных поисков?','Can the right input be prepared once instead of repeatedly searched?'],docs:['planner-optimizer.html','using-explain.html','runtime-config-query.html'],book:[438,456],steps:[
    s('Есть клиенты 1 и 2. Хотим связать их с заказами по customer_id.','We have customers 1 and 2. Join them to orders by customer_id.',[tab('customers','Внешний вход','Outer input',['id'],[['1'],['2']])],[], 'CREATE TEMP TABLE nl_c (id integer);\nINSERT INTO nl_c VALUES (1),(2);\nCREATE TEMP TABLE nl_o (id integer, customer_id integer);\nINSERT INTO nl_o VALUES (10,1),(11,1),(12,3);', 'Внешний и внутренний вход — роли узлов плана. Планировщик может выбрать порядок, отличный от написанного в SQL.','Outer and inner are plan-node roles. The planner may choose an order different from the SQL spelling.'),
    s('Для клиента 1 внутренний просмотр проверяет три заказа. Подходят 10 и 11.','For customer 1, the inner scan checks three orders. Orders 10 and 11 match.',[tab('customers','Текущая внешняя строка','Current outer row',['id'],[['1']]),tab('orders','Внутренний вход','Inner input',['id','customer_id'],[['10','1'],['11','1'],['12','3']]),tab('result','Пары','Pairs',['customer','order'],[['1','10'],['1','11']])],[f('customers','orders','customer = 1','internal'),f('orders','result','2 matches','internal')], 'SELECT c.id, o.id FROM nl_c c JOIN nl_o o ON o.customer_id = c.id;', 'Простой Nested Loop перебирает внутренние строки для текущей внешней. Условие соединения отбрасывает заказ 12.','A simple Nested Loop visits inner rows for the current outer row. The join condition rejects order 12.'),
    s('Для клиента 2 внутренний просмотр начинается заново. Совпадений нет: результат остаётся из двух строк.','For customer 2, the inner scan restarts. No matches: the result stays at two rows.',[tab('customers','Текущая внешняя строка','Current outer row',['id'],[['2']]),tab('orders','Внутренний вход','Inner input',['id','customer_id'],[['10','1'],['11','1'],['12','3']]),tab('result','Пары','Pairs',['customer','order'],[['1','10'],['1','11']]),box('work','Сравнения','Comparisons',['2 x 3 = 6'])],[f('customers','orders','customer = 2','internal')], '', 'Здесь полный внутренний просмотр повторяется дважды. Отсутствующая пара не создаёт строку для INNER JOIN.','Here the full inner scan repeats twice. An absent match does not create an INNER JOIN result row.'),
    s('Внутренний узел имеет loops = 2. Materialize может сохранить его вход вместо повторного чтения таблицы.','The inner node has loops = 2. Materialize may retain its input rather than reread the table.',[plan([['join','Nested Loop'],['outer','Seq Scan nl_c'],['mat','Materialize'],['inner','Seq Scan nl_o']],[['join','outer'],['join','mat'],['mat','inner']]),box('stored','Сохранённый вход','Retained input',['10, 11, 12'])],[f('plan','stored','reuse rows','internal')], '', 'Materialize — возможная оптимизация, а не обязательный узел каждого Nested Loop. Повторное сравнение строк не обязательно означает повторный дисковый I/O.','Materialize is optional, not part of every Nested Loop. Repeated comparisons do not necessarily imply repeated disk I/O.'),
    s('С индексом по customer_id внутренний поиск может сразу взять заказы нужного клиента.','An index on customer_id can let the inner scan fetch only the current customer’s orders.',[plan([['join','Nested Loop'],['outer','Seq Scan nl_c'],['inner','Index Scan: customer_id']],[['join','outer'],['join','inner']]),tree('idx','Параметризованный поиск','Parameterized lookup',[['root','customer_id'],['one','1 -> 10, 11'],['three','3 -> 12']],[['root','one'],['root','three']]),tab('result','Пары','Pairs',['customer','order'],[['1','10'],['1','11']])],[f('plan','idx','1, then 2','internal'),f('idx','result','matching rows','internal')], 'CREATE INDEX ON nl_o (customer_id);', 'Это возможный путь при подходящих оценках, не обещание выбора индекса на маленькой таблице. Значение внешней строки становится ключом внутреннего поиска.','This is a possible path at suitable costs, not a promise to use an index on a tiny table. The outer value parameterizes the inner lookup.'),
    s('Повторим клиента 1 во входе: Memoize может вернуть его два заказа из кеша, сохранив обе пары ещё раз.','Repeat customer 1 in the input: Memoize can reuse its two orders while emitting both pairs again.',[tab('customers','Новый внешний вход','New outer input',['id'],[['1'],['1'],['2']]),tab('cache','Memoize по параметру','Memoize by parameter',['key','cached orders'],[['1','10, 11'],['2','empty']]),box('work','Проверки кеша','Cache lookups',['1: miss; 1: hit; 2: miss','4 output pairs'])],[f('customers','cache','lookup parameter','internal')], 'INSERT INTO nl_c VALUES (1);', 'Показан возможный Memoize-план для нового входа в порядке 1,1,2. Кеш не удаляет повторения результата и может вытеснять записи при нехватке памяти.','This is a possible Memoize plan with a new input visited as 1,1,2. Caching preserves result duplicates and may evict entries when memory fills.'),
  ]}),
  c({number:49,id:'hash-join',group:6,title:['Подготовить хеш-таблицу и искать в ней','Build a hash table, then probe'],question:['Зачем заново искать пары, если ключи одной стороны можно подготовить заранее?','Why repeat searches when one side’s keys can be prepared in advance?'],next:['А если оба входа уже упорядочены по ключу?','What if both inputs are already ordered by the join key?'],docs:['planner-optimizer.html','using-explain.html','runtime-config-resource.html'],book:[457,482],steps:[
    s('Справа R1 и R2 с ключом 1, R3 с ключом 3. Сделаем этот вход стороной построения.','The right input has R1 and R2 with key 1, and R3 with key 3. Use it as the build side.',[joinR()],[],joinSetup, 'Роли build и probe выбирает план. Здесь правая сторона выбрана для понятного примера, а не из-за обязательного порядка SQL.','The plan chooses build and probe roles. The right side is selected for this example, not mandated by SQL order.'),
    s('В фазе build ключ 1 связывается с R1 и R2, а ключ 3 — с R3. Все дубликаты сохраняются.','During build, key 1 stores R1 and R2; key 3 stores R3. Every duplicate is retained.',[joinR(),bucket(['1: R1, R2','3: R3'])],[f('right','hash','build','internal')], '', 'Рисунок группирует по ключам для ясности. Реальные hash buckets могут содержать коллизии; совпадение хеша ещё проверяют сравнением ключей.','The drawing groups by join key for clarity. Real hash buckets can contain collisions; equal hashes still require checking key equality.'),
    s('Probe для L1 с ключом 1 находит две строки. Получаются L1 + R1 и L1 + R2.','Probing L1 with key 1 finds two rows: L1 + R1 and L1 + R2.',[tab('left','Текущая probe-строка','Current probe row',['rid','k'],[['L1','1']]),bucket(['1: R1, R2','3: R3']),pairs([['L1','R1'],['L1','R2']])],[f('left','hash','probe 1','internal'),f('hash','result','2 pairs','internal')], 'SELECT l.rid, r.rid FROM join_l l JOIN join_r r ON l.k = r.k;', 'Обычно build-вход нужно подготовить до выдачи этих пар. Hash Join не требует отдельного пользовательского Hash-индекса.','The build input is normally prepared before emitting these pairs. Hash Join does not require a user-created Hash index.'),
    s('Для L3 с ключом 2 совпадения нет. INNER JOIN не добавляет строку.','L3 with key 2 has no match. INNER JOIN adds no row.',[tab('left','Текущая probe-строка','Current probe row',['rid','k'],[['L3','2']]),bucket(['1: R1, R2','3: R3']),pairs([['L1','R1'],['L1','R2']])],[f('left','hash','probe 2: miss','internal')], '', 'Порядок probe-строк на схеме выбран для объяснения. У OUTER JOIN несовпавшая сохраняемая сторона обрабатывается по её отдельным правилам.','The diagram chooses a probe order for teaching. An OUTER JOIN separately applies its preservation rules to unmatched rows.'),
    s('L2 тоже имеет ключ 1 и добавляет ещё две пары. Итог тот же: четыре, как у INNER JOIN раньше.','L2 also has key 1 and adds two more pairs. The total is the same four rows as before.',[tab('left','Текущая probe-строка','Current probe row',['rid','k'],[['L2','1']]),bucket(['1: R1, R2','3: R3']),pairs(matched)],[f('left','hash','probe 1 again','internal'),f('hash','result','two more pairs','internal')], '', 'Алгоритм меняет способ получить ответ, а не кратность равных ключей. Обычное равенство по-прежнему не соединяет NULL с NULL.','The algorithm changes how the answer is obtained, not duplicate-key multiplicity. Ordinary equality still does not match NULL with NULL.'),
    s('На большом входе хеш-таблица может не поместиться. Тогда работа делится на batches с временными файлами.','On a large input, the hash table may not fit. Work is then split into batches using temporary files.',[bucket(['current batch in memory']),seq('temp','Другие batches','Other batches',['build rows -> temp','probe rows -> temp','load next matching batch'])],[f('hash','temp','spill partitions','internal')], '', 'Это увеличенный пример, не spill трёх строк выше. Партиции обеих сторон должны соответствовать; Batches в EXPLAIN помогает увидеть такую работу.','This is a larger example, not a spill of the three rows above. Corresponding partitions of both inputs must match; EXPLAIN Batches exposes this work.'),
  ]}),
  c({number:50,id:'merge-join',group:6,title:['Свести два упорядоченных потока','Merge two ordered streams'],question:['Можно ли искать пары движением вперёд по двум отсортированным входам?','Can pairs be found by moving through two sorted inputs?'],next:['Индексы умеют не только обычное равенство. Разберём остальные способы поиска.','Indexes do more than ordinary equality. Explore the other access methods next.'],docs:['planner-optimizer.html','using-explain.html','queries-order.html'],book:[483,508],steps:[
    s('Поток слева приходит как 2, 1, 1. Для Merge Join сначала нужен порядок по ключу.','The left stream arrives as 2, 1, 1. Merge Join first needs join-key order.',[tab('left','Неупорядоченный вход','Unordered input',['rid','k'],[['L3','2'],['L1','1'],['L2','1']])],[],joinSetup, 'Это допустимый порядок входного потока, а не гарантированный порядок хранения. Упорядочение обеспечат Sort либо подходящий индексный путь.','This is a possible input-stream order, not a storage-order guarantee. A Sort or suitable index path must supply ordering.'),
    s('Теперь оба входа упорядочены: слева 1, 1, 2; справа 1, 1, 3. Сравниваем первые ключи.','Both inputs are now ordered: 1, 1, 2 on the left and 1, 1, 3 on the right. Compare their first keys.',[joinL(),joinR(),plan([['merge','Merge Join: k'],['ls','Sort left by k'],['rs','Sort right by k']],[['merge','ls'],['merge','rs']])],[f('left','right','1 = 1','internal')], 'SELECT l.rid, r.rid FROM join_l l JOIN join_r r ON l.k = r.k;', 'Возможный план содержит Sort с обеих сторон. Если нужный порядок уже есть, сортировка может не понадобиться.','A possible plan has Sort on each side. Existing suitable ordering can avoid a sort.'),
    s('Ключ L1 равен ключам R1 и R2. Первая левая строка даёт две пары.','L1 matches both R1 and R2, so the first left row yields two pairs.',[tab('left','Текущая левая строка','Current left row',['rid','k'],[['L1','1']]),joinR(),pairs([['L1','R1'],['L1','R2']])],[f('left','right','equal-key run','internal'),f('right','result','2 pairs','internal')], '', 'Одинаковый ключ справа образует группу, а не одну выбранную запись. Нужно сохранить возможность вернуться к её началу.','Equal right-side keys form a run, not one chosen row. The algorithm must be able to revisit the start of that run.'),
    s('Следующая L2 тоже имеет ключ 1. Повторяем правую группу и добавляем ещё две пары.','L2 also has key 1. Revisit the right run and add two more pairs.',[tab('left','Текущая левая строка','Current left row',['rid','k'],[['L2','1']]),tab('right','Повтор группы ключа 1','Revisit key-1 run',['rid','k'],[['R1','1'],['R2','1']]),pairs(matched)],[f('left','right','rescan equal run','internal'),f('right','result','two more pairs','internal')], '', 'Простое одновременное продвижение обоих курсоров потеряло бы пары. Обработка дубликатов важна и в алгоритме Merge Join.','Advancing both cursors once would lose pairs. Duplicate handling is essential to Merge Join too.'),
    s('Остались L3 с 2 и R3 с 3. Двигаем меньший ключ слева; левый вход заканчивается.','L3 has 2 and R3 has 3. Advance the smaller left key; the left input ends.',[tab('left','Левый вход','Left input',['rid','k'],[['L3','2']]),tab('right','Правый вход','Right input',['rid','k'],[['R3','3']]),pairs(matched)],[f('left','right','2 < 3: advance left','internal')], '', 'Для INNER JOIN дальнейших пар нет. Внешние соединения дополнительно сохраняют нужные несовпавшие строки; алгоритм не меняет семантику результата.','INNER JOIN has no further pairs. Outer joins additionally preserve required unmatched rows; the algorithm does not change result semantics.'),
    s('Получены те же четыре пары. Порядок входов нужен алгоритму, а порядок ответа задаётся ORDER BY.','The same four pairs result. Input ordering serves the algorithm; ORDER BY specifies result ordering.',[pairs(matched),box('order','Явное обещание порядка','Explicit ordering promise',['ORDER BY l.rid, r.rid'])],[], 'SELECT l.rid, r.rid FROM join_l l JOIN join_r r ON l.k = r.k ORDER BY l.rid, r.rid;', 'Общая стоимость включает получение упорядоченных входов. Условно линейный проход после сортировки не делает сортировку бесплатной.','Total cost includes obtaining ordered inputs. A roughly linear merge pass does not make sorting free.'),
  ]}),
];
